import { graph, graphql } from '../fb-graph';
import { getToken } from '../fb-token';
import { isGraphError } from '../types';
import type { AdAccount } from '../../features/adaccounts';
import type { ToolRunner } from './index';
import { primitiveToolValues } from './index';

const KEEP_ID_INFO_DOC_ID = '5664358410294804';
const NEW_ID_DOC_ID = '4831122253676348';

const CURRENCY_KEEP_VALUE = '__keep__';
const COUNTRY_KEEP_VALUE = '__keep__';

type ChangeInfoPart = 'timezone' | 'currency' | 'info';

interface PartResult {
  part: ChangeInfoPart;
  ok: boolean;
  message: string;
}

interface BillingUpdateResponse {
  data?: {
    billable_account_update?: {
      billable_account?: {
        id?: string;
      };
    };
  };
}

interface NewBillingAccountResponse {
  data?: {
    new_billable_account_from_old?: {
      id?: string;
      billable_account?: {
        id?: string;
      };
    };
  };
}

function bareAccountId(account: AdAccount): string {
  return account.id.startsWith('act_') ? account.id.slice(4) : account.id;
}

function readString(values: Record<string, string | boolean>, key: string): string {
  const value = values[key];
  return typeof value === 'string' ? value.trim() : '';
}

function upperCode(value: string): string {
  return value.trim().toUpperCase();
}

function selectedCountryCode(values: Record<string, string | boolean>): string {
  const selected = upperCode(readString(values, 'countryCode'));
  return selected && selected !== COUNTRY_KEEP_VALUE.toUpperCase() ? selected : '';
}

function countryCodeForPayload(values: Record<string, string | boolean>, account: AdAccount): string {
  return selectedCountryCode(values) || upperCode(account.country ?? '');
}

function randomBetween(min: number, max: number): number {
  return min + Math.floor(Math.random() * (max - min + 1));
}

function spinText(text: string): string {
  let output = text;
  const re = /{([^{}]+?)}/;
  let match = re.exec(output);
  while (match) {
    const options = match[1]?.split('|') ?? [];
    const pick = options[Math.floor(Math.random() * options.length)] ?? '';
    output = output.replace(match[0], pick);
    match = re.exec(output);
  }
  return output;
}

function timezonePartsFromValue(value: string): { id: string; timezone: string } {
  const trimmed = value.trim();
  const separatorIndex = trimmed.indexOf('|');
  if (separatorIndex === -1) return { id: trimmed, timezone: trimmed };
  return {
    id: trimmed.slice(0, separatorIndex).trim(),
    timezone: trimmed.slice(separatorIndex + 1).trim(),
  };
}

function timezoneNameFromValue(value: string): string {
  return timezonePartsFromValue(value).timezone;
}

function timezoneIdFromValue(value: string): string {
  return timezonePartsFromValue(value).id;
}

function isPersonalUse(values: Record<string, string | boolean>): boolean {
  const value = values.isPersonalUse;
  if (typeof value === 'boolean') return value;
  return value === 'true';
}

const RANDOM_API_DELAY_MIN_MS = 1000;
const RANDOM_API_DELAY_MAX_MS = 3000;

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => window.setTimeout(resolve, ms));
}

function randomApiDelayMs(): number {
  return randomBetween(RANDOM_API_DELAY_MIN_MS, RANDOM_API_DELAY_MAX_MS);
}

async function waitBetweenChangeInfoApiCalls(): Promise<void> {
  await sleep(randomApiDelayMs());
}

const TIMEZONE_KEEP_VALUE = '__keep__';

function selectedParts(values: Record<string, string | boolean>): ChangeInfoPart[] {
  const parts: ChangeInfoPart[] = [];
  const timezone = readString(values, 'timezoneName');
  if (timezone && timezone !== TIMEZONE_KEEP_VALUE) parts.push('timezone');
  if (readString(values, 'currency') && readString(values, 'currency') !== CURRENCY_KEEP_VALUE) parts.push('currency');
  if (selectedCountryCode(values) || hasBusinessInfoValues(values)) parts.push('info');
  return parts;
}

function hasBusinessInfoValues(values: Record<string, string | boolean>): boolean {
  return ['businessName', 'taxId', 'street1', 'street2', 'city', 'state', 'zip'].some((key) => readString(values, key) !== '');
}

function validateKeepId(values: Record<string, string | boolean>, parts: ChangeInfoPart[], account: AdAccount): string | null {
  if (parts.length === 0) return 'Chọn ít nhất một phần cần đổi khi giữ ID';
  if (parts.includes('currency') && !readString(values, 'currency')) return 'Thiếu tiền tệ';
  if (parts.includes('timezone') && !readString(values, 'timezoneName')) return 'Thiếu múi giờ';
  if (parts.includes('info') && !countryCodeForPayload(values, account)) return 'Thiếu mã quốc gia';
  return null;
}

function validateNewId(values: Record<string, string | boolean>, parts: ChangeInfoPart[], account: AdAccount): string | null {
  if (parts.length === 0) return 'Chọn ít nhất một phần cần đổi khi thay đổi ID TKQC';
  if (!countryCodeForPayload(values, account)) return 'Thiếu mã quốc gia để đổi ID mới';
  if (parts.includes('currency') && !readString(values, 'currency')) return 'Thiếu tiền tệ';
  if (parts.includes('timezone') && !readString(values, 'timezoneName')) return 'Thiếu múi giờ';
  return null;
}

function taxPayload(values: Record<string, string | boolean>, countryCode: string): {
  business_address: {
    country_code: string;
    city: string;
    state: string;
    street1: string;
    street2: string;
    zip: string;
  };
  business_name: string;
  is_personal_use: boolean;
  tax_id: string;
  tax_registration_status: string;
  second_tax_id?: string;
  tax_id_type?: string;
} {
  return {
    business_address: {
      country_code: countryCode,
      city: spinText(readString(values, 'city')),
      state: spinText(readString(values, 'state')),
      street1: spinText(readString(values, 'street1')),
      street2: spinText(readString(values, 'street2')),
      zip: spinText(readString(values, 'zip')),
    },
    business_name: spinText(readString(values, 'businessName')),
    is_personal_use: isPersonalUse(values),
    tax_id: spinText(readString(values, 'taxId')),
    tax_registration_status: '',
  };
}

function loggingData(): { logging_counter: number; logging_id: string; client_mutation_id: string } {
  return {
    logging_counter: randomBetween(10, 40),
    logging_id: `1017${randomBetween(500000, 700000)}`,
    client_mutation_id: String(randomBetween(1, 30)),
  };
}

async function changeTimezoneKeepId(adId: string, timezoneId: string): Promise<PartResult> {
  const res = await graph<{ success?: boolean }>(`/act_${adId}`, {
    method: 'POST',
    params: { method: 'POST', timezone_id: timezoneId },
  });
  if (isGraphError(res)) return { part: 'timezone', ok: false, message: res.message };
  if (res.success === true) return { part: 'timezone', ok: true, message: `Timezone ID ${timezoneId}` };
  return { part: 'timezone', ok: false, message: 'Facebook không xác nhận đổi timezone' };
}

async function changeCurrencyKeepId(adId: string, currency: string): Promise<PartResult> {
  const res = await graph<{ success?: boolean }>(`/act_${adId}`, {
    method: 'POST',
    params: { method: 'POST', currency },
  });
  if (isGraphError(res)) return { part: 'currency', ok: false, message: res.message };
  if (res.success === true) return { part: 'currency', ok: true, message: `Tiền tệ ${currency}` };
  return { part: 'currency', ok: false, message: 'Facebook không xác nhận đổi tiền tệ' };
}

async function changeInfoKeepId(
  account: AdAccount,
  values: Record<string, string | boolean>,
  actorId: string
): Promise<PartResult> {
  const adId = bareAccountId(account);
  const countryCode = countryCodeForPayload(values, account);
  const log = loggingData();
  const tax = { ...taxPayload(values, countryCode), second_tax_id: '' };
  const res = await graphql<BillingUpdateResponse>(
    {
      doc_id: KEEP_ID_INFO_DOC_ID,
      variables: JSON.stringify({
        input: {
          billable_account_payment_legacy_account_id: adId,
          currency: null,
          timezone: null,
          logging_data: {
            logging_counter: log.logging_counter,
            logging_id: log.logging_id,
          },
          tax,
          actor_id: actorId,
          client_mutation_id: log.client_mutation_id,
        },
      }),
    },
    'business'
  );
  if (isGraphError(res)) return { part: 'info', ok: false, message: res.message };
  if (res.data?.billable_account_update?.billable_account?.id) {
    return { part: 'info', ok: true, message: 'Đã đổi thông tin DN/thuế/địa chỉ' };
  }
  return { part: 'info', ok: false, message: 'Facebook không xác nhận đổi thông tin' };
}

async function changeInfoNewId(
  account: AdAccount,
  values: Record<string, string | boolean>,
  actorId: string,
  parts: ChangeInfoPart[]
): Promise<{ ok: boolean; message: string }> {
  const adId = bareAccountId(account);
  const countryCode = countryCodeForPayload(values, account);
  const currency = parts.includes('currency') ? upperCode(readString(values, 'currency')) : null;
  const timezoneName = parts.includes('timezone') && readString(values, 'timezoneName')
    ? timezoneNameFromValue(readString(values, 'timezoneName'))
    : null;
  const log = loggingData();
  const tax = { ...taxPayload(values, countryCode), tax_id_type: 'NONE' };
  const res = await graphql<NewBillingAccountResponse>(
    {
      doc_id: NEW_ID_DOC_ID,
      variables: JSON.stringify({
        input: {
          current_payment_legacy_account_id: adId,
          logging_data: {
            logging_counter: log.logging_counter,
            logging_id: log.logging_id,
          },
          new_country_code: countryCode,
          new_currency_code: currency,
          new_timezone: timezoneName,
          new_tax: tax,
          actor_id: actorId,
          client_mutation_id: log.client_mutation_id,
        },
      }),
    },
    'business'
  );
  if (isGraphError(res)) return { ok: false, message: res.message };

  const newAccountId = res.data?.new_billable_account_from_old?.id
    ?? res.data?.new_billable_account_from_old?.billable_account?.id;
  if (newAccountId) {
    return { ok: true, message: `Đã tạo TKQC ID mới ${newAccountId}. Hãy quét lại danh sách để cập nhật cache.` };
  }
  return { ok: false, message: 'Facebook không xác nhận tạo TKQC ID mới' };
}

export const changeInfoAccount: ToolRunner = async (account, rawValues) => {
  const values = primitiveToolValues(rawValues);
  const adId = bareAccountId(account);
  const changeId = values.changeId === true;
  const parts = selectedParts(values);

  if (changeId) {
    const validation = validateNewId(values, parts, account);
    if (validation) return { ok: false, message: validation };
    const { user_id } = await getToken();
    return changeInfoNewId(account, values, user_id, parts);
  }

  const validation = validateKeepId(values, parts, account);
  if (validation) return { ok: false, message: validation };

  const { user_id } = await getToken();
  const results: PartResult[] = [];
  for (const [partIndex, part] of parts.entries()) {
    if (partIndex > 0) await waitBetweenChangeInfoApiCalls();
    if (part === 'timezone') results.push(await changeTimezoneKeepId(adId, timezoneIdFromValue(readString(values, 'timezoneName'))));
    if (part === 'currency') results.push(await changeCurrencyKeepId(adId, upperCode(readString(values, 'currency'))));
    if (part === 'info') results.push(await changeInfoKeepId(account, values, user_id));
  }

  const failed = results.filter((result) => !result.ok);
  const message = results.map((result) => `${result.part}: ${result.ok ? 'OK' : `FAIL (${result.message})`}`).join('; ');
  if (failed.length === 0) {
    const patch: Partial<AdAccount> = {};
    if (parts.includes('currency')) patch.currency = upperCode(readString(values, 'currency'));
    if (parts.includes('timezone')) patch.timezone = timezoneNameFromValue(readString(values, 'timezoneName'));
    if (parts.includes('info')) patch.country = countryCodeForPayload(values, account);
    return { ok: true, message, patch };
  }
  if (failed.length < results.length) return { ok: false, message: `PARTIAL — ${message}` };
  return { ok: false, message };
};
