<script setup lang="ts">
import { onMounted, reactive, ref, watch } from 'vue';
import { Button, Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@mf2/shared-ui';
import { Table } from '@mf2/shared-ui/table';
import AdAccountAdminsDialog from './AdAccountAdminsDialog.vue';
import SpendLimitDialog from './SpendLimitDialog.vue';
import { useAccountList } from '../composables/use-account-list';
import { useAccountSelection } from '../composables/use-account-selection';
import type { AdAccount } from '../types/account-list.types';

interface Props {
  toolbarTarget?: string | HTMLElement;
}

defineProps<Props>();

const { accounts, isLoading, error, ensureLoaded, refresh, applyPatches } = useAccountList();
const { selectedIds } = useAccountSelection();
const adminsDialogOpen = ref(false);
const adminsDialogAccount = ref<AdAccount | null>(null);
const spendLimitDialogOpen = ref(false);
const spendLimitDialogAccount = ref<AdAccount | null>(null);

// Load the real account list on first mount; the grid refresh button reloads it.
onMounted(ensureLoaded);

// Facebook account_status code -> display meta. Unknown codes fall back to a
// neutral light chip so the status column stays consistent with DataGrid cells.
const STATUS_META: Record<number, { label: string; class: string }> = {
  1: { label: 'Hoạt động', class: 'border-[#BFD8CC] bg-[#F3F7F5] text-[#3C9944]' },
  2: { label: 'Vô hiệu hóa', class: 'border-[#FECACA] bg-[#FFF1F0] text-[#B42318]' },
  3: { label: 'Cần thanh toán', class: 'border-[#F0D48A] bg-[#FFF8E6] text-[#9A6700]' },
  7: { label: 'Đang xem xét', class: 'border-[#F0D48A] bg-[#FFF8E6] text-[#9A6700]' },
  8: { label: 'Đang giải quyết', class: 'border-[#F0D48A] bg-[#FFF8E6] text-[#9A6700]' },
  9: { label: 'Ân hạn', class: 'border-[#F0D48A] bg-[#FFF8E6] text-[#9A6700]' },
  100: { label: 'Đóng kín', class: 'border-[#D8E9E1] bg-[#F6F7F7] text-[#5E6360]' },
  101: { label: 'Đóng', class: 'border-[#D8E9E1] bg-[#F6F7F7] text-[#5E6360]' },
  201: { label: 'ANY_ACTIVE', class: 'border-[#D8E9E1] bg-[#F6F7F7] text-[#5E6360]' },
  202: { label: 'ANY_CLOSED', class: 'border-[#D8E9E1] bg-[#F6F7F7] text-[#5E6360]' },
};

const statusMeta = (code: number) =>
  STATUS_META[code] ?? { label: `Mã ${code}`, class: 'border-[#D8E9E1] bg-[#F6F7F7] text-[#5E6360]' };

function formatNumber(value: unknown): string {
  const num = Number(value);
  if (!Number.isFinite(num)) return '-';
  return new Intl.NumberFormat('vi-VN', { maximumFractionDigits: 2 }).format(num);
}

function spendLimitPercent(row: Record<string, any>): number | null {
  const limit = Number(row.spendLimit);
  if (!Number.isFinite(limit) || limit <= 0) return null;

  const spent = Number(row.spent ?? 0);
  if (!Number.isFinite(spent) || spent <= 0) return 0;

  return Math.min(100, Math.max(0, Math.round((spent / limit) * 100)));
}

function spendLimitWidth(row: Record<string, any>): string {
  return `${spendLimitPercent(row) ?? 0}%`;
}

function spendLimitTooltip(row: Record<string, any>): string {
  const limit = Number(row.spendLimit);
  if (!Number.isFinite(limit) || limit <= 0) return 'Chưa đặt giới hạn chi tiêu';

  const spent = Number(row.spent ?? 0);
  return `${formatNumber(Number.isFinite(spent) ? spent : 0)} / ${formatNumber(limit)}`;
}

// Copy formatter mirrors the on-screen text so paste into Excel matches what the
// user sees (Vietnamese status label) instead of the raw status code.
const formatCopyValue = (key: string, row: Record<string, any>): string | undefined => {
  if (key === 'status') return statusMeta(row.status as number).label;
  if (key === 'paymentStatus') return paymentStatusLabel(row.paymentStatus as string | undefined);
  if (key === 'holdNeed') return row.holdNeed as string | undefined;
  if (key === 'adminCount') return row.adminSummary as string | undefined;
  if (key === 'spendLimit') return spendLimitTooltip(row);
  if (key === 'priskRestrictions' && Array.isArray(row.priskRestrictions)) return row.priskRestrictions.join(', ');
  return undefined;
};

const columns = [
  { field: 'status', name: 'Trạng thái', width: 150 },
  { field: 'name', name: 'Tài khoản', width: 260 },
  { field: 'id', name: 'ID TKQC', width: 180 },
  { field: 'balance', name: 'Số dư', width: 120 },
  { field: 'threshold', name: 'Ngưỡng', width: 120 },
  { field: 'limit', name: 'Limit', width: 110 },
  { field: 'spent', name: 'Tổng tiêu', width: 120 },
  { field: 'currency', name: 'Tiền tệ', width: 90 },
  { field: 'ownership', name: 'Quyền', width: 130 },
  { field: 'spendLimit', name: 'Giới hạn chi tiêu', width: 160 },
  { field: 'paymentStatus', name: 'Thanh toán', width: 130 },
  { field: 'created', name: 'Ngày tạo', width: 160 },
  { field: 'type', name: 'Loại TK', width: 110 },
  { field: 'timezone', name: 'Múi giờ', width: 180 },
  { field: 'bmName', name: 'BM', width: 180 },
  { field: 'country', name: 'Quốc gia', width: 100 },
  { field: 'note', name: 'Ghi chú', width: 160 },
  { field: 'remainThreshold', name: 'Ngưỡng còn lại', width: 140 },
  { field: 'billDate', name: 'Ngày lập hóa đơn', width: 150 },
  { field: 'daysToDue', name: 'Ngày đến hạn TT', width: 140 },
  { field: 'lockReason', name: 'Lý do khóa', width: 140 },
  { field: 'hiddenLimit', name: 'Limit ẩn', width: 120 },
  { field: 'adminCount', name: 'SL Admin', width: 100 },
  { field: 'line2Bm', name: 'Dòng 2 BM', width: 180 },
  { field: 'ownerName', name: 'Chủ sở hữu', width: 160 },
  { field: 'holdNeed', name: 'HOLD/NEED', width: 260 },
];

const paymentStatusLabel = (status?: string) => {
  if (status === 'loaded') return 'Đã tải';
  if (status === 'error') return 'Lỗi';
  if (status === 'unavailable') return 'Không có';
  return 'Bỏ qua';
};

function openAdminsDialog(row: Record<string, any>): void {
  adminsDialogAccount.value = row as AdAccount;
  adminsDialogOpen.value = true;
}

function openSpendLimitDialog(row: Record<string, any>): void {
  spendLimitDialogAccount.value = row as AdAccount;
  spendLimitDialogOpen.value = true;
}

function applyAdminPatch(accountId: string, patch: Partial<AdAccount>): void {
  applyPatches(new Map([[accountId, patch]]));
  if (adminsDialogAccount.value?.id === accountId) {
    adminsDialogAccount.value = { ...adminsDialogAccount.value, ...patch };
  }
}

function applySpendLimitPatch(accountId: string, patch: Partial<AdAccount>): void {
  applyPatches(new Map([[accountId, patch]]));
  if (spendLimitDialogAccount.value?.id === accountId) {
    spendLimitDialogAccount.value = { ...spendLimitDialogAccount.value, ...patch };
  }
}

// shared-ui Table owns the row/header checkboxes and mutates checkedConfig.selected
// directly (its row-select emits are declared-but-never-emitted). To keep the Pinia
// selection store as the single source of truth, mirror both ways with member-equality
// guards so neither watcher loops: Table edits checkedConfig -> store; store edits -> grid.
const checkedConfig = reactive({
  selected: [...selectedIds.value],
  is_select_all: false,
});

const sameMembers = (list: string[], set: Set<string>) =>
  list.length === set.size && list.every((id) => set.has(id));

watch(
  () => checkedConfig.selected,
  (next) => {
    if (sameMembers(next, selectedIds.value)) return;
    selectedIds.value = new Set(next);
  },
  { deep: true }
);

watch(
  selectedIds,
  (next) => {
    if (sameMembers(checkedConfig.selected, next)) return;
    checkedConfig.selected = [...next];
  },
  { deep: true }
);
</script>

<template>
  <div class="flex h-full flex-col overflow-hidden rounded-xl border border-white/10 bg-transparent">
    <p v-if="error" class="border-b border-red-500/20 bg-red-500/10 px-4 py-2 text-xs text-red-300">
      {{ error }}
    </p>

    <div class="min-h-0 flex-1 overflow-hidden">
      <Table
        :data="accounts"
        :columns="columns"
        :loading="isLoading"
        :checked-config="checkedConfig"
        :table_info="{ name: 'ad-accounts', key_id: 'id' }"
        :tools="['refresh', 'time', 'custom-column', 'zoom', 'download']"
        :toolbar-target="toolbarTarget"
        :format-copy-value="formatCopyValue"
        enable-range-select
        show-checkbox
        @refresh="refresh"
      >
        <template #status="{ value }">
          <span
            class="tkqc-status-chip inline-flex items-center rounded-full border px-2 py-0.5 text-xs font-medium"
            :class="statusMeta(value as number).class"
          >
            {{ statusMeta(value as number).label }}
          </span>
        </template>
        <template #paymentStatus="{ value, row }">
          <span class="text-xs text-white/80">{{ paymentStatusLabel(value as string | undefined) }}</span>
          <span v-if="(row as Record<string, any>).payment" class="ml-1 text-xs text-white/35">
            {{ (row as Record<string, any>).payment }}
          </span>
        </template>
        <template #spendLimit="{ row }">
          <TooltipProvider :delay-duration="120">
            <Tooltip>
              <TooltipTrigger as-child>
                <div class="tkqc-spend-limit-cell" @click.stop="openSpendLimitDialog(row as Record<string, any>)">
                  <template v-if="spendLimitPercent(row as Record<string, any>) !== null">
                    <div class="tkqc-spend-limit-track" aria-hidden="true">
                      <span
                        class="tkqc-spend-limit-bar"
                        :style="{ width: spendLimitWidth(row as Record<string, any>) }"
                      />
                    </div>
                    <span class="tkqc-spend-limit-percent">
                      {{ spendLimitPercent(row as Record<string, any>) }}%
                    </span>
                  </template>
                  <span v-else class="tkqc-spend-limit-empty">-</span>
                </div>
              </TooltipTrigger>
              <TooltipContent class="max-w-[240px] text-xs leading-relaxed">
                {{ spendLimitTooltip(row as Record<string, any>) }}
              </TooltipContent>
            </Tooltip>
          </TooltipProvider>
        </template>
        <template #holdNeed="{ value }">
          <span class="text-xs text-amber-300">{{ value || '-' }}</span>
        </template>
        <template #adminCount="{ row }">
          <Button
            variant="ghost"
            size="sm"
            class="h-7 rounded-full px-2 text-xs font-medium text-violet-200 hover:bg-violet-500/15 hover:text-white"
            @click.stop="openAdminsDialog(row as Record<string, any>)"
          >
            {{ (row as Record<string, any>).adminSummary || '-' }}
          </Button>
        </template>

      </Table>
    </div>
    <AdAccountAdminsDialog
      v-model:open="adminsDialogOpen"
      :account="adminsDialogAccount"
      @patched="applyAdminPatch"
    />
    <SpendLimitDialog
      v-model:open="spendLimitDialogOpen"
      :account="spendLimitDialogAccount"
      @patched="applySpendLimitPatch"
    />
  </div>
</template>

<style scoped>
:deep(.row-cell > .tkqc-status-chip) {
  flex: 0 0 auto;
  width: fit-content;
  max-width: 100%;
  white-space: nowrap;
}

:deep(.row-cell > .tkqc-spend-limit-cell) {
  flex: 1 1 auto;
}

.tkqc-spend-limit-cell {
  display: flex;
  min-width: 0;
  width: 100%;
  align-items: center;
  gap: 8px;
  cursor: pointer;
}

.tkqc-spend-limit-cell:hover .tkqc-spend-limit-track {
  background: #DCEBE3;
}

.tkqc-spend-limit-track {
  position: relative;
  height: 8px;
  min-width: 42px;
  flex: 1 1 auto;
  overflow: hidden;
  border-radius: 999px;
  background: #E7ECEA;
}

.tkqc-spend-limit-bar {
  position: absolute;
  inset: 0 auto 0 0;
  border-radius: inherit;
  background: linear-gradient(270deg, #73C258 0%, #3C9944 100%);
}

.tkqc-spend-limit-percent {
  min-width: 32px;
  flex: 0 0 auto;
  text-align: right;
  font-size: 12px;
  font-weight: 500;
  color: #26352D;
}

.tkqc-spend-limit-empty {
  font-size: 12px;
  font-weight: 500;
  color: #8B9690;
}
</style>
