import { graphql } from '../fb-graph';
import { getToken } from '../fb-token';
import { extFetch } from '../smit-connect';
import { isGraphError } from '../types';
import type { ToolRunner } from './index';
import { primitiveToolValues } from './index';

const LANDING_DOC_ID = '27042179815412290';
const REVIEW_DOC_ID = '25448543034774360';
const PAY_NOW_DOC_ID = '24676694655347193';
const MAX_3DS_RETRIES = 2;

interface MoneyAmount {
  amount?: string | number | null;
  amount_with_offset?: string | number | null;
  currency?: string | null;
}

interface PaymentMethodNode {
  credential_id?: string | null;
  id?: string | null;
  credential_type?: string | null;
  type?: string | null;
  display_string?: string | null;
  display?: string | null;
}

interface BillableAccountNode {
  account_balance_with_offset?: MoneyAmount | null;
  account_balance?: MoneyAmount | null;
  selected_payment_card_key?: string | null;
  selected_payment_method_key?: string | null;
  payment_methods?: { data?: PaymentMethodNode[] | null } | PaymentMethodNode[] | null;
  all_payment_methods?: {
    pm_credit_card?: { data?: PaymentMethodNode[] | null } | null;
  } | null;
}

interface LandingResponse {
  data?: {
    payment_account?: {
      billable_account?: BillableAccountNode | null;
    } | null;
  };
}

interface PayNowResponse {
  data?: Record<string, unknown>;
}

interface CardChoice {
  credentialId: string;
  credentialType: string;
  display: string;
  isPrimary: boolean;
}

interface DebtInfo {
  amount: string;
  amountWithOffset: string;
  currency: string;
  cards: CardChoice[];
}

interface NextActionInfo {
  url: string;
}

function bareId(id: string): string {
  return id.startsWith('act_') ? id.slice(4) : id;
}

function toFinitePositiveNumber(value: string): number {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
}

function encodeBase64Utf8(value: string): string {
  const bytes = new TextEncoder().encode(value);
  let binary = '';
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary);
}

function uuid(): string {
  return globalThis.crypto?.randomUUID?.() ?? `${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

function normalizeCurrency(currency: string | null | undefined): string {
  const normalized = String(currency ?? '').trim().toUpperCase();
  return normalized || 'USD';
}

function buildPlatformTrustToken(amountWithOffset: string, credentialId: string, currency: string): string {
  const inner = {
    data: {
      amount: String(amountWithOffset),
      cred_id: String(credentialId),
      currency,
    },
    nonce: uuid(),
    op: 'CHARGE',
    ver: 1,
  };
  return encodeBase64Utf8(JSON.stringify({
    payload: encodeBase64Utf8(JSON.stringify(inner)),
    signatures: [],
  }));
}

function collectPaymentMethods(billable: BillableAccountNode): PaymentMethodNode[] {
  const methods: PaymentMethodNode[] = [];
  const direct = billable.payment_methods;
  if (Array.isArray(direct)) methods.push(...direct);
  else if (direct?.data) methods.push(...direct.data);
  const creditCards = billable.all_payment_methods?.pm_credit_card?.data;
  if (creditCards) methods.push(...creditCards);
  return methods;
}

function cardLast4(value: string): string {
  const digits = value.replace(/\D/g, '');
  return digits.length >= 4 ? digits.slice(-4) : digits;
}

function normalizeCard(method: PaymentMethodNode, selectedKey: string): CardChoice | null {
  const credentialId = method.credential_id ?? method.id;
  if (!credentialId) return null;
  const display = String(method.display_string ?? method.display ?? credentialId);
  return {
    credentialId: String(credentialId),
    credentialType: String(method.credential_type ?? method.type ?? 'CREDIT_CARD').toUpperCase(),
    display,
    isPrimary: selectedKey !== '' && String(credentialId) === selectedKey,
  };
}

function resolveCards(billable: BillableAccountNode): CardChoice[] {
  const selectedKey = String(billable.selected_payment_card_key ?? billable.selected_payment_method_key ?? '');
  const byId = new Map<string, CardChoice>();
  for (const method of collectPaymentMethods(billable)) {
    const card = normalizeCard(method, selectedKey);
    if (card) byId.set(card.credentialId, card);
  }
  if (selectedKey && !byId.has(selectedKey)) {
    byId.set(selectedKey, {
      credentialId: selectedKey,
      credentialType: 'CREDIT_CARD',
      display: selectedKey,
      isPrimary: true,
    });
  }
  const cards = Array.from(byId.values());
  return cards.sort((a, b) => Number(b.isPrimary) - Number(a.isPrimary));
}

function parseDebtInfo(res: LandingResponse): DebtInfo | { skip: string } | { error: string } {
  const billable = res.data?.payment_account?.billable_account;
  if (!billable) return { error: 'Landing không trả billable_account' };

  const balance = billable.account_balance_with_offset ?? billable.account_balance;
  const amount = String(balance?.amount ?? '').trim();
  if (!amount || toFinitePositiveNumber(amount) <= 0) return { skip: 'Không có dư nợ cần trả' };

  const cards = resolveCards(billable);
  if (cards.length === 0) return { error: 'Không có thẻ thanh toán hiển thị' };

  return {
    amount,
    amountWithOffset: String(balance?.amount_with_offset ?? amount).trim() || amount,
    currency: normalizeCurrency(balance?.currency),
    cards,
  };
}

function findNextAction(value: unknown): NextActionInfo | null {
  if (!value || typeof value !== 'object') return null;
  const record = value as Record<string, unknown>;
  const rawUrl = record.external_uri ?? record.external_url ?? record.url;
  if (typeof rawUrl === 'string' && isAllowed3dsUrl(rawUrl)) return { url: rawUrl };
  for (const child of Object.values(record)) {
    if (Array.isArray(child)) {
      for (const item of child) {
        const found = findNextAction(item);
        if (found) return found;
      }
    } else if (child && typeof child === 'object') {
      const found = findNextAction(child);
      if (found) return found;
    }
  }
  return null;
}

function isAllowed3dsUrl(rawUrl: string): boolean {
  try {
    const url = new URL(rawUrl, 'https://business.facebook.com');
    return /(^|\.)facebook\.com$/i.test(url.hostname) && url.pathname.includes('/payments/3ds_');
  } catch {
    return false;
  }
}

function hasPayNowSuccess(value: unknown): boolean {
  if (!value || typeof value !== 'object') return false;
  const json = JSON.stringify(value).toLowerCase();
  return json.includes('billable_account') || json.includes('payment_account');
}

function parseRequestedLast4(values: Record<string, string | boolean>): { last4: string; error?: string } {
  const raw = typeof values.cardLast4 === 'string' ? values.cardLast4.trim() : '';
  if (!raw) return { last4: '' };
  const digits = raw.replace(/\D/g, '');
  if (!/^\d{4}$/.test(digits)) return { last4: '', error: '4 số cuối thẻ phải gồm đúng 4 chữ số' };
  return { last4: digits };
}

function selectCandidateCards(debt: DebtInfo, last4: string): CardChoice[] | { error: string } {
  if (!last4) return debt.cards;
  if (!/^\d{4}$/.test(last4)) return { error: '4 số cuối thẻ phải gồm đúng 4 chữ số' };
  const matched = debt.cards.filter((card) => cardLast4(card.display) === last4 || cardLast4(card.credentialId) === last4);
  if (matched.length === 0) return { error: `Không tìm thấy thẻ có 4 số cuối ${last4}` };
  return matched;
}

async function loadDebtInfo(adId: string): Promise<DebtInfo | { ok: true; message: string; skipped?: boolean } | { ok: false; message: string }> {
  const landing = await graphql<LandingResponse>(
    {
      fb_api_req_friendly_name: 'BillingPayNowLandingScreenQuery',
      doc_id: LANDING_DOC_ID,
      variables: JSON.stringify({ intent: 'PAY_NOW', paymentAccountID: String(adId) }),
    },
    'business'
  );
  if (isGraphError(landing)) return { ok: false, message: landing.message };

  const parsed = parseDebtInfo(landing);
  if ('skip' in parsed) return { ok: true, skipped: true, message: parsed.skip };
  if ('error' in parsed) return { ok: false, message: parsed.error };
  return parsed;
}

async function reviewPayment(adId: string, credentialId: string): Promise<{ ok: boolean; message?: string }> {
  const review = await graphql(
    {
      fb_api_req_friendly_name: 'BillingReviewPaymentScreenQuery',
      doc_id: REVIEW_DOC_ID,
      variables: JSON.stringify({
        creditCardID: String(credentialId),
        paymentAccountID: String(adId),
        sharedStoredBalanceID: '',
      }),
    },
    'business'
  );
  if (isGraphError(review)) return { ok: false, message: review.message };
  return { ok: true };
}

async function payNow(adId: string, actorId: string, debt: DebtInfo, card: CardChoice): Promise<PayNowResponse | { error: true; message: string }> {
  const externalFlowId = `upl_${Math.floor(Date.now() / 1000)}_${uuid()}`;
  const wizardSessionId = `rd_${Date.now()}_${uuid()}`;
  return graphql<PayNowResponse>(
    {
      fb_api_req_friendly_name: 'BillingPayNowOrSettleStatePayNowMutation',
      doc_id: PAY_NOW_DOC_ID,
      variables: JSON.stringify({
        input: {
          billable_account_payment_legacy_account_id: String(adId),
          credential_id: String(card.credentialId),
          payment_amount: { amount: String(debt.amount), currency: debt.currency },
          transaction_initiation_source: 'CUSTOMER',
          upl_logging_data: {
            billing_notification_id: '',
            context: 'billingpaynow',
            credential_id: String(card.credentialId),
            credential_type: card.credentialType || 'CREDIT_CARD',
            entry_point: 'BILLING_HUB',
            external_flow_id: externalFlowId,
            target_name: 'BillingPayNowOrSettleStatePayNowMutation',
            user_session_id: externalFlowId,
            wizard_config_name: 'PAY_NOW_BILLING_HUB',
            wizard_name: 'PAY_NOW',
            wizard_screen_name: 'pay_now_review_state_display',
            wizard_session_id: wizardSessionId,
          },
          platform_trust_token: buildPlatformTrustToken(debt.amountWithOffset, card.credentialId, debt.currency),
          actor_id: actorId,
          client_mutation_id: String(Date.now()),
        },
      }),
    },
    'business'
  );
}

async function handle3ds(nextAction: NextActionInfo): Promise<{ ok: boolean; message?: string }> {
  try {
    await extFetch(nextAction.url, {
      method: 'GET',
      headers: { 'cache-control': 'no-store' },
    });
    return { ok: true };
  } catch (error) {
    return { ok: false, message: error instanceof Error ? error.message : 'Không xử lý được xác minh 3DS' };
  }
}

async function payWithCard(adId: string, actorId: string, debt: DebtInfo, card: CardChoice): Promise<{ ok: boolean; message: string }> {
  const review = await reviewPayment(adId, card.credentialId);
  if (!review.ok) return { ok: false, message: `Review thẻ ${cardLast4(card.display) || card.display} thất bại: ${review.message ?? 'không rõ lỗi'}` };

  for (let attempt = 0; attempt <= MAX_3DS_RETRIES; attempt += 1) {
    const pay = await payNow(adId, actorId, debt, card);
    if (isGraphError(pay)) return { ok: false, message: pay.message };

    const nextAction = findNextAction(pay);
    if (!nextAction) {
      if (hasPayNowSuccess(pay)) {
        const suffix = cardLast4(card.display) || card.display;
        return { ok: true, message: `Đã thanh toán dư nợ ${debt.amount} ${debt.currency} bằng thẻ ${suffix}` };
      }
      return { ok: false, message: 'GraphQL không xác nhận được thanh toán dư nợ' };
    }

    if (attempt >= MAX_3DS_RETRIES) {
      return { ok: false, message: 'Chưa hoàn tất xác minh 3DS' };
    }

    const challenge = await handle3ds(nextAction);
    if (!challenge.ok) return { ok: false, message: `Không xử lý được xác minh 3DS: ${challenge.message ?? 'không rõ lỗi'}` };
  }

  return { ok: false, message: 'Chưa hoàn tất xác minh 3DS' };
}

export const payDebt: ToolRunner = async (account, rawValues) => {
  const values = primitiveToolValues(rawValues);
  const adId = bareId(account.id);
  if (!adId) return { ok: false, message: 'Thiếu ID tài khoản' };

  // V6 only sends payment requests for accounts whose FB account_status is 3
  // (billing/payment required). Keep the same cheap preflight so active/closed
  // accounts do not trigger billing GraphQL just to learn there is no debt.
  if (account.status !== 3) {
    return { ok: true, skipped: true, message: 'TKQC chưa cần thanh toán dư nợ' };
  }

  const requested = parseRequestedLast4(values);
  if (requested.error) return { ok: false, message: requested.error };

  const debt = await loadDebtInfo(adId);
  if ('ok' in debt) return debt;

  const candidates = selectCandidateCards(debt, requested.last4);
  if (!Array.isArray(candidates)) return { ok: false, message: candidates.error };

  const { user_id } = await getToken();
  const failures: string[] = [];
  for (const card of candidates) {
    const result = await payWithCard(adId, user_id, debt, card);
    if (result.ok) return result;
    failures.push(`${cardLast4(card.display) || card.display}: ${result.message}`);
  }

  const tried = requested.last4 ? `thẻ ${requested.last4}` : `${candidates.length} thẻ`;
  return { ok: false, message: `Thanh toán dư nợ thất bại với ${tried}: ${failures.join(' | ')}` };
};
