import { graph, graphql } from '../fb-graph';
import { getToken } from '../fb-token';
import { isGraphError } from '../types';
import type { AdAccount, CardData } from '../../features/adaccounts';
import type { ToolRunner } from './index';

const SET_DEFAULT_CARD_DOC_ID = '24268156329457050';
const UNKNOWN_CREDENTIAL_ID = 'Unknown';

interface CreditCardNode {
  credential_id?: string;
  display_string?: string;
}

interface PaymentMethodsResponse {
  all_payment_methods?: {
    pm_credit_card?: {
      data?: CreditCardNode[];
    };
  };
}

interface SetDefaultCardResponse {
  data?: unknown;
}

function bareId(id: string): string {
  return id.startsWith('act_') ? id.slice(4) : id;
}

function parseCardSuffix(value: unknown): string {
  return String(value ?? '').match(/\d{4}/)?.[0] ?? '';
}

function parseCreditCards(cards: CreditCardNode[] | undefined): CardData[] {
  return (cards ?? []).map((card) => {
    const displayString = card.display_string ?? '';
    return {
      display: displayString.match(/\d{4}(?!.*\d)/)?.[0] || displayString.match(/\d+/)?.[0] || UNKNOWN_CREDENTIAL_ID,
      type: displayString.toLowerCase().match(/[^\d\W]+/)?.[0],
      credential_id: card.credential_id || UNKNOWN_CREDENTIAL_ID,
    };
  });
}

async function fetchCardData(adId: string): Promise<CardData[]> {
  const res = await graph<PaymentMethodsResponse>(`/act_${adId}`, {
    method: 'GET',
    params: {
      fields: 'all_payment_methods{pm_credit_card{credential_id,display_string}}',
    },
    tokenPurpose: 'readGraph',
  });

  if (isGraphError(res)) throw new Error(res.message);
  return parseCreditCards(res.all_payment_methods?.pm_credit_card?.data);
}

async function resolveCardData(account: AdAccount, adId: string): Promise<CardData[]> {
  const freshCards = await fetchCardData(adId);
  if (freshCards.length > 0) return freshCards;
  return account.card_data ?? [];
}

function isUsableCard(card: CardData): boolean {
  return Boolean(card.credential_id && card.credential_id !== UNKNOWN_CREDENTIAL_ID);
}

function randomMutationId(): string {
  return String(Math.floor(Math.random() * 30) + 1);
}

export const setDefaultCard: ToolRunner = async (account, values) => {
  const suffix = parseCardSuffix(values.cardSuffix);
  if (!suffix) return { ok: false, message: 'Vui lòng nhập 4 số cuối thẻ cần đặt mặc định' };

  const adId = bareId(account.id || account.account_id || '');
  if (!adId) return { ok: false, message: 'Thiếu ID tài khoản quảng cáo' };

  const cards = await resolveCardData(account, adId);
  const targetCard = cards.find((card) => isUsableCard(card) && card.display.endsWith(suffix));
  if (!targetCard) {
    return { ok: true, skipped: true, message: `Không tìm thấy thẻ khớp 4 số cuối ${suffix}` };
  }

  const { user_id } = await getToken();
  const res = await graphql<SetDefaultCardResponse>({
    doc_id: SET_DEFAULT_CARD_DOC_ID,
    variables: JSON.stringify({
      input: {
        billable_account_payment_legacy_account_id: adId,
        primary_funding_id: targetCard.credential_id,
        actor_id: user_id,
        client_mutation_id: randomMutationId(),
      },
    }),
  }, 'www');

  if (isGraphError(res)) return { ok: false, message: res.message };

  return {
    ok: true,
    message: `Đã set thẻ mặc định ${targetCard.display}`,
    patch: { payment: targetCard.display },
  };
};
