import * as XLSX from 'xlsx';
import { graph } from '../fb-graph';
import { isGraphError } from '../types';
import type { ToolRunner } from './index';

interface GraphIdResponse {
  id?: string;
}

const ZERO_DECIMAL_CURRENCIES = new Set(['VND', 'JPY', 'KRW', 'IDR', 'CLP', 'COP', 'CRC', 'HUF', 'ISK', 'PYG', 'TWD', 'UGX']);

function bareId(id: string): string {
  return id.startsWith('act_') ? id.slice(4) : id;
}

function pick(row: Record<string, string>, ...keys: string[]): string {
  for (const key of keys) {
    const direct = row[key];
    if (direct?.trim()) return direct.trim();
    const foundKey = Object.keys(row).find((candidate) => candidate.toLowerCase() === key.toLowerCase());
    if (foundKey && row[foundKey]?.trim()) return row[foundKey].trim();
  }
  return '';
}

function mapStatus(value: string): 'ACTIVE' | 'PAUSED' {
  return value.toLowerCase().includes('active') || value.toLowerCase() === 'on' ? 'ACTIVE' : 'PAUSED';
}

function mapObjective(value: string): string {
  const normalized = value.trim().toLowerCase();
  if (normalized.includes('sales')) return 'OUTCOME_SALES';
  if (normalized.includes('lead')) return 'OUTCOME_LEADS';
  if (normalized.includes('engagement')) return 'OUTCOME_ENGAGEMENT';
  if (normalized.includes('awareness')) return 'OUTCOME_AWARENESS';
  if (normalized.includes('app')) return 'OUTCOME_APP_PROMOTION';
  return 'OUTCOME_TRAFFIC';
}

function mapBidStrategy(value: string): string {
  const normalized = value.trim().toLowerCase();
  if (normalized.includes('cost')) return 'COST_CAP';
  if (normalized.includes('bid cap')) return 'LOWEST_COST_WITH_BID_CAP';
  return 'LOWEST_COST_WITHOUT_CAP';
}

function normalizeBudget(value: string, currency: string): number | null {
  const amount = Number(value.replace(/[^\d.]/g, ''));
  if (!Number.isFinite(amount) || amount <= 0) return null;
  return ZERO_DECIMAL_CURRENCIES.has(currency.toUpperCase()) ? Math.round(amount) : Math.round(amount * 100);
}

async function getCurrency(adId: string): Promise<string> {
  const res = await graph<{ currency?: string }>(`/act_${adId}`, {
    version: 'v18.0',
    params: { fields: 'currency' },
    tokenPurpose: 'powerEditorAction',
  });
  if (isGraphError(res)) throw new Error(res.message);
  return res.currency || 'USD';
}

async function createNode(path: string, body: Record<string, string | number | boolean>): Promise<string> {
  const res = await graph<GraphIdResponse>(path, {
    version: 'v18.0',
    method: 'POST',
    tokenPurpose: 'powerEditorAction',
    body,
  });
  if (isGraphError(res)) throw new Error(res.message);
  if (!res.id) throw new Error(`Graph không trả id cho ${path}: ${JSON.stringify(res)}`);
  return res.id;
}

async function runRow(adId: string, currency: string, row: Record<string, string>): Promise<string> {
  const campaignName = pick(row, 'Campaign Name');
  const adSetName = pick(row, 'Ad Set Name');
  const adName = pick(row, 'Ad Name');
  const pageId = pick(row, 'Link Object ID').replace(/^o:/, '');
  const link = pick(row, 'Link');
  const body = pick(row, 'Body');
  if (!campaignName || !adSetName || !adName || !pageId || !link) {
    throw new Error('Dòng XLSX thiếu Campaign Name / Ad Set Name / Ad Name / Link Object ID / Link');
  }

  const campaignId = await createNode(`/act_${adId}/campaigns`, {
    name: campaignName,
    objective: mapObjective(pick(row, 'Campaign Objective', 'Objective')),
    status: mapStatus(pick(row, 'Campaign Status')),
    special_ad_categories: pick(row, 'Special Ad Categories') || 'None',
    buying_type: pick(row, 'Buying Type') || 'AUCTION',
  });

  const countries = (pick(row, 'Countries') || 'VN').split(/[;,|]/).map((country) => country.trim()).filter(Boolean);
  const targeting = {
    geo_locations: { countries },
    age_min: Number(pick(row, 'Age Min')) || 18,
    age_max: Number(pick(row, 'Age Max')) || 65,
  };
  const budget = normalizeBudget(pick(row, 'Ad Set Daily Budget', 'Daily Budget'), currency);
  const adsetBody: Record<string, string | number | boolean> = {
    name: adSetName,
    campaign_id: campaignId,
    status: mapStatus(pick(row, 'Ad Set Status')),
    targeting: JSON.stringify(targeting),
    billing_event: pick(row, 'Billing Event') || 'IMPRESSIONS',
    optimization_goal: pick(row, 'Optimization Goal') || 'LANDING_PAGE_VIEWS',
    destination_type: pick(row, 'Destination Type') || 'UNDEFINED',
    bid_strategy: mapBidStrategy(pick(row, 'Ad Set Bid Strategy', 'Bid Strategy')),
  };
  if (budget) adsetBody.daily_budget = budget;
  const adsetId = await createNode(`/act_${adId}/adsets`, adsetBody);

  const storyId = pick(row, 'Story ID');
  const creativeBody: Record<string, string | number | boolean> = { name: adName };
  if (storyId) {
    creativeBody.object_story_id = storyId;
  } else {
    const linkData: Record<string, unknown> = {
      message: body,
      link,
      call_to_action: { type: pick(row, 'Call to Action') || 'LEARN_MORE', value: { link } },
    };
    const imageHash = pick(row, 'Image Hash');
    if (imageHash) linkData.image_hash = imageHash;
    creativeBody.object_story_spec = JSON.stringify({ page_id: pageId, link_data: linkData });
  }
  const creativeId = await createNode(`/act_${adId}/adcreatives`, creativeBody);

  const adIdCreated = await createNode(`/act_${adId}/ads`, {
    name: adName,
    adset_id: adsetId,
    creative: JSON.stringify({ creative_id: creativeId }),
    status: mapStatus(pick(row, 'Ad Status')),
  });

  return `${campaignId}/${adsetId}/${creativeId}/${adIdCreated}`;
}

export const importCampaignXlsx: ToolRunner = async (account, values) => {
  const adId = bareId(account.id || account.account_id || '');
  if (!adId) return { ok: false, message: 'Thiếu ID tài khoản quảng cáo' };

  const fileValue = values.xlsxFile;
  if (!(fileValue instanceof File)) {
    return { ok: false, message: 'Vui lòng chọn file XLSX thật trước khi chạy; runner không dùng tên file để tránh fake success.' };
  }

  const workbook = XLSX.read(await fileValue.arrayBuffer(), { type: 'array' });
  const sheet = workbook.Sheets[workbook.SheetNames[0] ?? ''];
  if (!sheet) return { ok: false, message: 'File XLSX không có sheet dữ liệu' };
  const rows = XLSX.utils.sheet_to_json<Record<string, string | number | boolean | null>>(sheet, { defval: '' })
    .map((row) => Object.fromEntries(Object.entries(row).map(([key, value]) => [key, String(value ?? '')])));
  if (rows.length === 0) return { ok: false, message: 'Không parse được dữ liệu XLSX' };

  const currency = await getCurrency(adId);
  const created: string[] = [];
  for (const row of rows) {
    created.push(await runRow(adId, currency, row));
  }

  return { ok: true, message: `Đã tạo ${created.length} dòng camp/ad từ ${fileValue.name}: ${created.join('; ')}` };
};
