<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import {
  Button,
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  Input,
} from '@mf2/shared-ui';
import { Icon, type IconName } from '@mf2/shared-ui/icons';
import { toast } from '@mf2/shared-ui/sonner';
import { spendLimit } from '../../../api/tools/spend-limit';
import type { AdAccount } from '../types/account-list.types';

type SpendLimitMode = 'set' | 'reset' | 'remove';

const props = defineProps<{
  open: boolean;
  account: AdAccount | null;
}>();

const emit = defineEmits<{
  (event: 'update:open', value: boolean): void;
  (event: 'patched', accountId: string, patch: Partial<AdAccount>): void;
}>();

const mode = ref<SpendLimitMode>('set');
const amount = ref('');
const running = ref(false);

const currency = computed(() => props.account?.currency || 'VND');
const spent = computed(() => props.account?.spent ?? 0);
const currentLimit = computed(() => props.account?.spendLimit ?? 0);
const remainingLimit = computed(() => Math.max(0, currentLimit.value - spent.value));
const hasCurrentLimit = computed(() => Number.isFinite(currentLimit.value) && currentLimit.value > 0);

const actionOptions: Array<{ value: SpendLimitMode; label: string; icon: IconName }> = [
  { value: 'set', label: 'Đổi giới hạn', icon: 'pencil' },
  { value: 'reset', label: 'Reset giới hạn', icon: 'refresh-cw' },
  { value: 'remove', label: 'Xoá giới hạn', icon: 'trash-2' },
];

const submitLabel = computed(() => actionOptions.find((option) => option.value === mode.value)?.label ?? 'Áp dụng');

const helperText = computed(() => {
  if (mode.value === 'reset') return 'Số tiền đã chi tiêu sẽ là 0 sau khi reset.';
  if (mode.value === 'remove') return 'Sẽ gỡ bỏ giới hạn chi tiêu, TKQC chi không giới hạn.';
  return 'Khi đổi giới hạn, mức mới phải lớn hơn số đã chi tiêu.';
});

watch(
  () => props.open,
  (open) => {
    if (!open) return;
    mode.value = 'set';
    amount.value = hasCurrentLimit.value ? String(Math.max(currentLimit.value, spent.value + 1)) : String(Math.max(1, spent.value + 1));
    running.value = false;
  }
);

function formatMoney(value: unknown): string {
  const num = Number(value);
  if (!Number.isFinite(num)) return `- ${currency.value}`;
  return `${new Intl.NumberFormat('vi-VN', { maximumFractionDigits: 2 }).format(num)} ${currency.value}`;
}

function accountId(account: AdAccount): string {
  return account.account_id || account.id.replace(/^act_/, '');
}

function validate(): string | null {
  if (!props.account) return 'Thiếu tài khoản TKQC';
  if (mode.value !== 'set') return null;

  const nextAmount = Number(amount.value);
  if (!Number.isFinite(nextAmount) || nextAmount <= 0) return 'Mức giới hạn mới phải là số dương';
  if (nextAmount <= spent.value) return 'Mức giới hạn mới phải lớn hơn số đã chi tiêu';
  return null;
}

async function submit(): Promise<void> {
  const account = props.account;
  const validation = validate();
  if (validation) {
    toast.error(validation);
    return;
  }
  if (!account) return;

  running.value = true;
  try {
    const values: Record<string, string | boolean> = mode.value === 'set'
      ? { mode: 'set', amount: amount.value }
      : { mode: mode.value };
    const result = await spendLimit(account, values, 0, { allAccounts: [account], selectedCount: 1, delayMs: 0 });

    if (!result.ok) {
      toast.error(result.message);
      return;
    }

    if (result.patch) emit('patched', account.id, result.patch);
    toast.success(result.message);
    emit('update:open', false);
  } catch (error) {
    toast.error(error instanceof Error ? error.message : String(error));
  } finally {
    running.value = false;
  }
}
</script>

<template>
  <Dialog :open="open" @update:open="emit('update:open', $event)">
    <DialogContent
      class="max-w-[min(460px,calc(100vw-40px))] overflow-hidden rounded-[22px] border border-[#DCEBE3] bg-[#F8FFFA] p-0 text-[#1F2A24] shadow-[0_24px_70px_rgba(31,42,36,0.18)]"
    >
      <DialogHeader class="px-5 pb-2 pt-5 pr-12">
        <DialogTitle class="flex items-center gap-2 text-base font-medium tracking-[-0.02em] text-[#17211B]">
          <span class="grid size-9 place-items-center rounded-full bg-[#EAF7F0] text-[#3C9944] shadow-sm ring-1 ring-[#BFD8CC]">
            <Icon name="bar-chart-2" :size="16" />
          </span>
          Đặt giới hạn chi tiêu
        </DialogTitle>
      </DialogHeader>

      <div v-if="account" class="space-y-4 px-5 pb-5 pt-2">
        <section class="rounded-[20px] bg-white p-4 shadow-[0_12px_28px_rgba(31,42,36,0.06)] ring-1 ring-[#DCEBE3]">
          <div class="rounded-[16px] bg-[#F3F7F5] px-3 py-3 ring-1 ring-[#DCEBE3]">
            <p class="truncate text-sm font-medium tracking-[-0.02em] text-[#17211B]">{{ account.name }}</p>
            <p class="mt-1 text-xs text-[#7A8580]">{{ accountId(account) }}</p>
          </div>

          <div class="mt-4 space-y-1.5">
            <p class="text-sm font-semibold text-[#17211B]">
              Số tiền còn lại:
              <span class="font-semibold text-[#2E7D32]">{{ hasCurrentLimit ? formatMoney(remainingLimit) : '-' }}</span>
            </p>
            <p class="text-xs font-medium text-[#4C5A52]">
              Đã tiêu:
              <span class="font-semibold text-[#2E7D32]">{{ formatMoney(spent) }}</span>
              <span class="mx-2 text-[#B3C5BC]">·</span>
              Giới hạn:
              <span class="font-semibold text-[#2E7D32]">{{ hasCurrentLimit ? formatMoney(currentLimit) : '-' }}</span>
            </p>
          </div>

          <div class="my-4 h-px bg-[#E1ECE6]" />

          <p class="text-xs leading-relaxed text-[#6E7772]">
            {{ helperText }}
          </p>
        </section>

        <section class="space-y-2.5">
          <p class="text-[11px] font-semibold uppercase tracking-[0.08em] text-[#6E7772]">Chọn hành động</p>
          <div class="flex flex-wrap items-center gap-2">
            <button
              v-for="option in actionOptions"
              :key="option.value"
              type="button"
              class="inline-flex h-10 items-center justify-center gap-1.5 rounded-full border bg-white px-3 text-center text-xs font-medium transition hover:border-[#BFD8CC] hover:bg-[#F8FFFA] hover:text-[#2E7D32]"
              :class="mode === option.value ? 'border-[#3C9944] !bg-[#EAF7F0] text-[#2E7D32] ring-2 ring-[#73C258]/20' : 'border-[#DCEBE3] text-[#4C5A52]'"
              :disabled="running"
              @click="mode = option.value"
            >
              <Icon :name="option.icon" :size="13" />
              <span>{{ option.label }}</span>
            </button>
          </div>
        </section>

        <section
          class="space-y-2.5 transition-opacity"
          :class="mode !== 'set' ? 'opacity-50' : ''"
        >
          <label class="text-[11px] font-semibold uppercase tracking-[0.08em] text-[#6E7772]" for="spend-limit-amount">
            Mức giới hạn chi tiêu mới
          </label>
          <div class="flex items-center gap-2 rounded-[16px] bg-white p-2 shadow-sm ring-1 ring-[#DCEBE3] focus-within:ring-[#73C258]">
            <Input
              id="spend-limit-amount"
              v-model="amount"
              type="number"
              class="h-11 flex-1 border-0 bg-transparent px-2 text-base font-medium text-[#17211B] shadow-none ring-0 focus-visible:ring-0"
              placeholder="10000"
              :disabled="running || mode !== 'set'"
            />
            <span class="shrink-0 rounded-full bg-[#F3F7F5] px-3 py-1.5 text-xs font-medium text-[#4C5A52] ring-1 ring-[#DCEBE3]">
              {{ currency }}
            </span>
          </div>
        </section>

        <div class="flex justify-end gap-2 pt-1">
          <Button
            type="button"
            variant="secondary"
            class="h-10 rounded-full bg-white px-4 text-[#4C5A52] ring-1 ring-[#DCEBE3] hover:bg-[#F8FFFA]"
            :disabled="running"
            @click="emit('update:open', false)"
          >
            Huỷ
          </Button>
          <Button type="button" class="h-10 rounded-full px-4" :disabled="running || !account" @click="submit">
            <Icon v-if="running" name="loader-2" class="mr-2 size-4 animate-spin" />
            {{ running ? 'Đang xử lý...' : submitLabel }}
          </Button>
        </div>
      </div>
    </DialogContent>
  </Dialog>
</template>
