import { graph } from '../../../api/fb-graph';
import { getToken } from '../../../api/fb-token';
import { isGraphError } from '../../../api/types';
import {
  bareAccountId,
  getBmIdForCurrentUser,
  loadAccountAdminContext,
  removeOneAdmin,
} from '../../../api/tools/remove-user-helpers';
import { classifyAdAccountUserRole, mapAdAccountAdminUsers, summarizeAdAccountAdmins } from './adaccount-mappers';
import type { AdAccount, AdAccountAdminUser } from '../types/account-list.types';

export type AdAccountAdminAction = 'promote' | 'demote' | 'remove';

const ROLE_IDS: Record<'admin' | 'analyst', number> = {
  admin: 1001,
  analyst: 1003,
};

interface ChangeUserRoleResponse {
  success?: boolean;
}

export interface AdAccountAdminActionResult {
  message: string;
  patch?: Partial<AdAccount>;
}

function accountNumericId(account: AdAccount): string {
  return bareAccountId(account.account_id || account.id);
}

async function changeUserRole(adId: string, uid: string, role: 'admin' | 'analyst'): Promise<void> {
  const res = await graph<ChangeUserRoleResponse>(`/act_${adId}/users`, {
    method: 'POST',
    tokenPurpose: 'powerEditorAction',
    params: {
      role: ROLE_IDS[role],
      uid,
    },
  });

  if (isGraphError(res)) throw new Error(res.message);
  if (res.success !== true) throw new Error('Graph không trả success=true; kết quả đổi quyền không xác định');
}

function buildAdminPatch(ctx: Awaited<ReturnType<typeof loadAccountAdminContext>>): Partial<AdAccount> | undefined {
  if (isGraphError(ctx)) return undefined;
  const users = mapAdAccountAdminUsers(ctx);
  const adminCount = users.filter((user) => user.role === 'admin').length;
  return {
    adminUsers: users,
    adminCount,
    nonAdminPermissionCount: users.length - adminCount,
    adminSummary: summarizeAdAccountAdmins(users),
  };
}

export async function getCurrentFacebookUserId(): Promise<string | undefined> {
  try {
    return (await getToken()).user_id;
  } catch {
    return undefined;
  }
}

export async function runAdAccountAdminAction(
  account: AdAccount,
  user: AdAccountAdminUser,
  action: AdAccountAdminAction
): Promise<AdAccountAdminActionResult> {
  const adId = accountNumericId(account);

  if (action === 'promote') {
    if (user.role === 'admin') return { message: `${user.name || user.id} đã là Admin.` };
    await changeUserRole(adId, user.id, 'admin');
  } else if (action === 'demote') {
    if (user.role === 'analyst') return { message: `${user.name || user.id} đã là Nhà Phân tích.` };
    await changeUserRole(adId, user.id, 'analyst');
  } else {
    const token = await getToken();
    const ctx = await loadAccountAdminContext(adId);
    if (isGraphError(ctx)) throw new Error(ctx.message);
    if (ctx.owner === user.id) throw new Error('Không thể xóa owner của TKQC.');
    const bmId = getBmIdForCurrentUser(ctx, token.user_id);
    const result = await removeOneAdmin(adId, user.id, bmId);
    if (!result.ok) throw new Error(result.message);
  }

  const refreshed = await loadAccountAdminContext(adId);
  const patch = buildAdminPatch(refreshed);
  const nextUser = patch?.adminUsers?.find((item) => item.id === user.id);
  const roleText = nextUser ? nextUser.roleLabel : user.roleLabel;

  if (action === 'promote') return { message: `Đã nâng quyền ${user.name || user.id} lên Admin.`, patch };
  if (action === 'demote') return { message: `Đã hạ quyền ${user.name || user.id} xuống ${roleText}.`, patch };
  return { message: `Đã xóa quản trị viên ${user.name || user.id}.`, patch };
}

export function roleLabelFromUser(user: AdAccountAdminUser): string {
  return user.roleLabel || (classifyAdAccountUserRole(user) === 'admin' ? 'Admin' : 'Nhà Phân tích');
}
