import { graphql } from '../fb-graph';
import { getToken } from '../fb-token';
import { isGraphError } from '../types';
import type { ToolRunner } from './index';

// Activate prepaid billing for an ad account.
// Source/spec: Xmeta + bmmanager both use the business GraphQL mutation below
// with a fixed recurring_enabled=false payload. There is no user config for this
// tool; one selected TKQC produces one mutation request.

const ACTIVATE_PREPAY_DOC_ID = '4886770528075857';

function bareId(id: string): string {
  return id.startsWith('act_') ? id.slice(4) : id;
}

export const activatePrepay: ToolRunner = async (account) => {
  const adId = bareId(account.id);
  if (!adId) return { ok: false, message: 'Thiếu ID tài khoản' };

  const { user_id } = await getToken();
  const res = await graphql(
    {
      fb_api_req_friendly_name: 'BillingPrepayActivateMutation',
      doc_id: ACTIVATE_PREPAY_DOC_ID,
      variables: JSON.stringify({
        input: {
          billable_account_payment_legacy_account_id: adId,
          recurring_enabled: false,
          actor_id: user_id,
          client_mutation_id: '3',
        },
      }),
    },
    'business'
  );

  if (isGraphError(res)) return { ok: false, message: res.message };

  // The source/spec contract for this tool is absence of GraphQL-level errors.
  // Do not add extra post-run REST verification here unless the product spec is
  // updated; live cause analysis is tracked separately by the user.
  return { ok: true, message: 'Đã kích hoạt trả trước (GraphQL)' };
};
