import { graph, graphql } from '../fb-graph';
import { getToken } from '../fb-token';
import { isGraphError } from '../types';
import type { ToolRunner } from './index';

// Spend limit (spend cap) management for ad accounts.
// Three modes:
//   set    — graph POST /act_<id> body { spend_cap: amount } (RAW currency unit, no ×100)
//   remove — graph POST /act_<id> body { spend_cap_action: 'delete' }
//   reset  — graphql doc_id 5205066939546485 resets amount_spent to 0 (spend_cap unchanged)
//
// RAW amount: Adscheck v6 sends the number as-is from the UI (spend_cap - 0 to coerce to number).
// FB stores spend_cap in the account's currency unit, same as what the user types.
// Do NOT multiply by 100 — that was a guess refuted by the v6 reference.

const RESET_SPEND_DOC_ID = '5205066939546485';

function bareId(id: string): string {
  return id.startsWith('act_') ? id.slice(4) : id;
}

export const spendLimit: ToolRunner = async (account, values) => {
  const mode = String(values.mode ?? '');
  if (mode !== 'set' && mode !== 'remove' && mode !== 'reset') {
    return { ok: false, message: 'Mode không hợp lệ (phải là set, remove, hoặc reset)' };
  }

  const adId = bareId(account.id);
  if (!adId) return { ok: false, message: 'Thiếu ID tài khoản' };

  if (mode === 'set') {
    const amount = Number(values.amount);
    if (!Number.isFinite(amount) || amount <= 0) {
      return { ok: false, message: 'Số tiền giới hạn phải là số dương' };
    }

    const res = await graph<{ success?: boolean }>(
      `/act_${adId}`,
      { method: 'POST', body: { spend_cap: amount }, tokenPurpose: 'powerEditorAction' }
    );
    if (isGraphError(res)) return { ok: false, message: res.message };
    if (res.success !== true) {
      return { ok: false, message: 'Graph không xác nhận được đặt giới hạn chi tiêu' };
    }
    return { ok: true, message: `Đã đặt giới hạn chi tiêu: ${amount}`, patch: { spendLimit: amount } };
  }

  if (mode === 'remove') {
    const res = await graph<{ success?: boolean }>(
      `/act_${adId}`,
      { method: 'POST', body: { spend_cap_action: 'delete' }, tokenPurpose: 'powerEditorAction' }
    );
    if (isGraphError(res)) return { ok: false, message: res.message };
    if (res.success !== true) {
      return { ok: false, message: 'Graph không xác nhận được gỡ giới hạn chi tiêu' };
    }
    return { ok: true, message: 'Đã gỡ giới hạn chi tiêu', patch: { spendLimit: 0 } };
  }

  // mode === 'reset'
  const { user_id } = await getToken();
  const res = await graphql<{
    data?: {
      billable_account_reset_spend_limit?: {
        billable_account?: { spending_info?: unknown };
      };
    };
  }>(
    {
      doc_id: RESET_SPEND_DOC_ID,
      variables: JSON.stringify({
        input: {
          billable_account_payment_legacy_account_id: adId,
          actor_id: user_id,
          client_mutation_id: '1',
        },
      }),
    },
    'www'
  );
  if (isGraphError(res)) return { ok: false, message: res.message };
  if (!res?.data?.billable_account_reset_spend_limit?.billable_account?.spending_info) {
    return { ok: false, message: 'GraphQL không xác nhận được reset số đã chi' };
  }
  return { ok: true, message: 'Đã reset số tiền đã chi về 0', patch: { spent: 0 } };
};
