import { getToken } from '../fb-token';
import { graph } from '../fb-graph';
import { isGraphError } from '../types';
import type { AdAccount } from '../../features/adaccounts';
import type { ToolRunner } from './index';
import {
  bareAccountId,
  getBmIdForCurrentUser,
  loadAccountAdminContext,
  removeOneAdmin,
  scrapeHiddenAdmins,
  shouldScrapeHiddenAdmins,
  wait,
} from './remove-user-helpers';

const ADMIN_ROLE_ID = 1001;
const MIN_UID_DELAY_MS = 1000;
const MAX_UID_DELAY_MS = 3000;

interface ShareAdminResponse {
  success?: boolean;
}

interface ParsedUids {
  valid: string[];
  skipped: string[];
}

function accountId(account: AdAccount): string {
  return bareAccountId(account.account_id || account.id);
}

function parseUidList(value: unknown): ParsedUids {
  if (typeof value !== 'string') return { valid: [], skipped: [] };

  const valid: string[] = [];
  const skipped: string[] = [];
  const seen = new Set<string>();
  const tokens = value
    .split(/[\r\n,]+/)
    .map((token) => token.trim())
    .filter(Boolean);

  for (const token of tokens) {
    if (!/^\d{6,}$/.test(token)) {
      skipped.push(`${token}:invalid`);
      continue;
    }
    if (seen.has(token)) {
      skipped.push(`${token}:duplicate`);
      continue;
    }
    seen.add(token);
    valid.push(token);
  }

  return { valid, skipped };
}

function randomShareDelayMs(): number {
  return MIN_UID_DELAY_MS + Math.floor(Math.random() * (MAX_UID_DELAY_MS - MIN_UID_DELAY_MS + 1));
}

async function shareAdmin(adId: string, uid: string): Promise<{ ok: boolean; message: string }> {
  const res = await graph<ShareAdminResponse>(`/act_${adId}/users`, {
    method: 'POST',
    tokenPurpose: 'powerEditorAction',
    params: {
      role: ADMIN_ROLE_ID,
      uid,
    },
  });

  if (isGraphError(res)) return { ok: false, message: res.message };
  if (res.success === true) return { ok: true, message: 'OK' };
  return { ok: false, message: 'Graph không trả success=true; kết quả chia sẻ QTV không xác định' };
}

function compactFailures(failures: Array<{ uid: string; reason: string }>): string {
  return failures.slice(0, 3).map((failure) => `${failure.uid}: ${failure.reason}`).join(' | ');
}

export const shareAdminThenRemoveAll: ToolRunner = async (account, values, _index, ctx) => {
  if (values.confirmTransfer !== true) {
    return {
      ok: false,
      message: 'Cần tick xác nhận trước khi chạy Chia sẻ QTV rồi xóa toàn bộ vai trò trong TKQC.',
    };
  }

  const { valid: targetUids, skipped } = parseUidList(values.uidList);
  if (targetUids.length === 0) {
    const skippedText = skipped.length > 0 ? ` · bỏ qua ${skipped.length} token (${skipped.slice(0, 3).join(', ')})` : '';
    return { ok: false, message: `no_valid_uid: Cần nhập ít nhất 1 UID QTV hợp lệ${skippedText}` };
  }

  const adId = accountId(account);
  const sharedUids: string[] = [];
  const shareFailures: Array<{ uid: string; reason: string }> = [];

  for (const uid of targetUids) {
    await wait(randomShareDelayMs());
    const result = await shareAdmin(adId, uid);
    if (result.ok) {
      sharedUids.push(uid);
    } else {
      shareFailures.push({ uid, reason: result.message });
    }
  }

  if (shareFailures.length > 0) {
    const status = sharedUids.length > 0 ? 'PARTIAL' : 'FAIL';
    return {
      ok: false,
      message: `${status} chia sẻ QTV ${sharedUids.length}/${targetUids.length}; dừng trước pha xóa để tránh mất quyền sai · ${compactFailures(shareFailures)}`,
    };
  }

  const token = await getToken();
  const accountCtx = await loadAccountAdminContext(adId);
  if (isGraphError(accountCtx)) {
    return {
      ok: false,
      message: `Đã chia sẻ QTV ${sharedUids.length}/${targetUids.length}, nhưng không load được danh sách vai trò để xóa: ${accountCtx.message}`,
    };
  }

  const normalUsers = accountCtx.users?.data ?? [];
  const userpermissions = accountCtx.userpermissions?.data ?? [];
  const hiddenCheck = await shouldScrapeHiddenAdmins(normalUsers, userpermissions);
  const ownerBusinessId = accountCtx.owner_business?.id ?? null;
  const hiddenUserIds = hiddenCheck.scrape ? await scrapeHiddenAdmins(adId, ownerBusinessId) : [];
  const detectMethod = hiddenCheck.scrape ? (hiddenCheck.fallback ? 'html_fallback' : 'batch_diff_then_html') : 'none';
  const bmId = getBmIdForCurrentUser(accountCtx, token.user_id);
  const protectedUids = new Set<string>(targetUids);
  if (accountCtx.owner) protectedUids.add(accountCtx.owner);

  const deleteTargets = Array.from(new Set(normalUsers.map((user) => user.id).concat(hiddenUserIds)))
    .filter((uid) => !protectedUids.has(uid));

  if (accountCtx.owner === token.user_id) {
    protectedUids.add(token.user_id);
  }

  if (deleteTargets.length === 0) {
    return {
      ok: true,
      message: `OK chia sẻ QTV ${sharedUids.length}/${targetUids.length}; không có UID cũ cần xóa · ẩn ${hiddenUserIds.length} · detect ${detectMethod}`,
    };
  }

  const deletedUids: string[] = [];
  const deleteFailures: Array<{ uid: string; reason: string }> = [];
  const methodCounts = new Map<string, number>();
  const deleteDelay = Math.max(0, Math.floor(ctx?.delayMs ?? 0) || 0);

  for (const uid of deleteTargets) {
    const result = await removeOneAdmin(adId, uid, bmId);
    if (result.ok) {
      deletedUids.push(uid);
      if (result.methodUsed) methodCounts.set(result.methodUsed, (methodCounts.get(result.methodUsed) ?? 0) + 1);
    } else {
      deleteFailures.push({ uid, reason: result.message });
    }
    if (deleteDelay > 0) await wait(deleteDelay);
  }

  const methodText = Array.from(methodCounts.entries()).map(([method, count]) => `${method}:${count}`).join(',') || 'none';
  const parts = [
    `chia sẻ QTV ${sharedUids.length}/${targetUids.length}`,
    `xóa vai trò cũ ${deletedUids.length}/${deleteTargets.length}`,
    `giữ ${protectedUids.size}`,
    `ẩn ${hiddenUserIds.length}`,
    `detect ${detectMethod}`,
    `method ${methodText}`,
  ];

  if (deleteFailures.length > 0) {
    parts.push(`lỗi: ${compactFailures(deleteFailures)}`);
    return { ok: false, message: `PARTIAL ${parts.join(' · ')}` };
  }

  return { ok: true, message: `OK ${parts.join(' · ')}` };
};
