import { graphql } from '../fb-graph';
import { getToken } from '../fb-token';
import { isGraphError } from '../types';
import type { ToolRunner } from './index';

const VIA_STATUS_DOC_ID = '5437070356383726';
const VIA_APPEAL_DOC_ID = '5329872773703511';
const ADACCOUNT_APPEAL_DOC_ID = '7045373122221158';

const DEFAULT_APPEAL_COMMENT = "I'm not sure which policy was violated.";

const ISSUE_COMMENTS: Record<string, string> = {
  '575839481422418': "I'm not sure which policy was violated.",
  '7628858420471655': 'I think there was unauthorized use of my Ad account.',
};

interface ViaStatusResponse {
  data?: {
    assetOwnerData?: {
      advertising_restriction_info?: {
        appeal_state?: string;
        status?: string;
      };
    };
  };
}

interface ViaAppealResponse {
  data?: {
    ale_banhammer_appeal_create?: {
      success?: boolean;
    };
  };
}

interface AdAccountAppealResponse {
  data?: {
    xfb_alr_ad_account_appeal_create?: {
      success?: boolean;
    };
  };
}

function bareId(id: string): string {
  return id.startsWith('act_') ? id.slice(4) : id;
}

function ownerIdFromAccount(account: Parameters<ToolRunner>[0]): string {
  return String(account.ownerId || account.owner_business?.id || account.bm || '').trim();
}

async function checkViaStatus(userId: string): Promise<string | null> {
  const res = await graphql<ViaStatusResponse>({
    doc_id: VIA_STATUS_DOC_ID,
    variables: JSON.stringify({ assetOwnerId: userId, startTime: 0 }),
  }, 'www');

  if (isGraphError(res)) return null;
  const info = res.data?.assetOwnerData?.advertising_restriction_info;
  return info?.appeal_state ?? info?.status ?? null;
}

async function appealVia(userId: string): Promise<{ ok: boolean; message: string; skipped?: boolean }> {
  const status = await checkViaStatus(userId);
  if (status === 'APPEAL_ACCEPTED' || status === 'APPEAL_PENDING') {
    return { ok: true, skipped: true, message: `Via đã có trạng thái kháng: ${status}` };
  }

  const res = await graphql<ViaAppealResponse>({
    doc_id: VIA_APPEAL_DOC_ID,
    variables: JSON.stringify({
      input: {
        client_mutation_id: '1',
        actor_id: userId,
        entity_id: userId,
        appeal_comment: DEFAULT_APPEAL_COMMENT,
        callsite: 'ACCOUNT_QUALITY',
      },
    }),
  }, 'www');

  if (isGraphError(res)) return { ok: false, message: res.message };
  if (res.data?.ale_banhammer_appeal_create?.success === true) {
    return { ok: true, message: 'Đã gửi kháng Via' };
  }
  return { ok: false, message: `FB chưa xác nhận kháng Via thành công: ${JSON.stringify(res)}` };
}

async function appealAdAccount(ownerId: string, adId: string, issueId: string, comment: string): Promise<{ ok: boolean; message: string; patch?: { appealStatus: string } }> {
  const res = await graphql<AdAccountAppealResponse>({
    doc_id: ADACCOUNT_APPEAL_DOC_ID,
    variables: JSON.stringify({
      input: {
        client_mutation_id: '1',
        actor_id: ownerId,
        ad_account_id: adId,
        ids_issue_ent_id: issueId,
        appeal_comment: comment,
        callsite: 'ACCOUNT_QUALITY',
      },
    }),
  }, 'business');

  if (isGraphError(res)) return { ok: false, message: res.message };
  if (res.data?.xfb_alr_ad_account_appeal_create?.success === true) {
    return { ok: true, message: 'Đã gửi kháng TKQC', patch: { appealStatus: 'ENTITY_HAS_PENDING_APPEAL' } };
  }
  return { ok: false, message: `FB chưa xác nhận kháng TKQC thành công: ${JSON.stringify(res)}` };
}

export const appealAccount: ToolRunner = async (account, values) => {
  const mode = String(values.mode ?? 'appeal_adaccount_disabled');
  const isAdAccountAppealMode =
    mode === 'appeal_adaccount_disabled' ||
    mode === 'appeal_adaccount_273' ||
    mode === 'appeal_adaccount';
  const adId = bareId(account.id || account.account_id || '');
  const token = await getToken();

  if (mode === 'appeal_via') return appealVia(token.user_id);
  if (!isAdAccountAppealMode) return { ok: false, message: 'Chế độ kháng không hợp lệ' };

  if (account.status !== 2) {
    return { ok: true, skipped: true, message: 'TKQC không ở trạng thái bị vô hiệu hóa (status != 2), bỏ qua kháng 273' };
  }

  const ownerId = ownerIdFromAccount(account);
  if (!ownerId) return { ok: false, message: 'Thiếu owner của TKQC để gửi kháng 273' };
  if (!adId) return { ok: false, message: 'Thiếu ID tài khoản quảng cáo' };

  const issueId = String(values.issueId ?? '575839481422418');
  const customComment = String(values.customComment ?? '').trim();
  const comment = issueId === '925653362567234' ? customComment : ISSUE_COMMENTS[issueId];
  if (!comment) return { ok: false, message: 'Vui lòng nhập nội dung kháng khi chọn Lý do khác' };

  return appealAdAccount(ownerId, adId, issueId, comment);
};
