import { graph } from '../fb-graph';
import { isGraphError } from '../types';
import type { AdAccount } from '../../features/adaccounts';
import type { ToolRunner } from './index';

const VALID_BM_ID_RE = /^\d{6,}$/;

const PARTNER_TASKS: Record<string, string[]> = {
  admin: ['ADVERTISE', 'ANALYZE', 'DRAFT', 'MANAGE'],
  advertiser: ['ADVERTISE', 'ANALYZE', 'DRAFT'],
  analyst: ['ANALYZE'],
};

interface ShareAgencyResponse {
  success?: boolean;
  id?: string;
}

function bareAccountId(account: AdAccount): string {
  if (account.account_id) return account.account_id;
  return account.id.startsWith('act_') ? account.id.slice(4) : account.id;
}

function ownerBusinessId(account: AdAccount): string | null {
  return account.owner_business?.id ?? account.bm ?? null;
}

function parsePartnerBmIds(value: unknown): {
  validIds: string[];
  skipped: Array<{ bmId: string; reason: string }>;
} {
  if (typeof value !== 'string') return { validIds: [], skipped: [] };

  const seen = new Set<string>();
  const validIds: string[] = [];
  const skipped: Array<{ bmId: string; reason: string }> = [];

  for (const id of value.split(/[\s,]+/).map((s) => s.trim()).filter(Boolean)) {
    if (!VALID_BM_ID_RE.test(id)) {
      skipped.push({ bmId: id, reason: 'invalid_or_duplicate_input' });
      continue;
    }
    if (seen.has(id)) {
      skipped.push({ bmId: id, reason: 'invalid_or_duplicate_input' });
      continue;
    }
    seen.add(id);
    validIds.push(id);
  }

  return { validIds, skipped };
}

function wait(ms: number): Promise<void> {
  return new Promise((resolve) => window.setTimeout(resolve, ms));
}

function randomPartnerDelayMs(): number {
  return Math.floor(Math.random() * 2001) + 1000;
}

async function shareOnePartner(
  adId: string,
  ownerBmId: string,
  partnerBmId: string,
  tasks: string[]
): Promise<{ ok: boolean; message: string }> {
  const res = await graph<ShareAgencyResponse>(`/act_${adId}/agencies`, {
    method: 'POST',
    tokenPurpose: 'businessManagerAction',
    version: 'v24.0',
    params: { __cppo: 1 },
    body: {
      accountId: adId,
      acting_brand_id: ownerBmId,
      business: partnerBmId,
      permitted_tasks: JSON.stringify(tasks),
    },
  });

  if (isGraphError(res)) return { ok: false, message: res.message };
  if (res.success === true || res.id != null) return { ok: true, message: 'success' };
  // HTTP 200 alone is not success — Graph omits success/id on some failures.
  return { ok: false, message: 'Graph không trả success=true hoặc id; kết quả không xác định' };
}

export const sharePartner: ToolRunner = async (account, values) => {
  const adId = bareAccountId(account);
  const ownerBmId = ownerBusinessId(account);

  if (!ownerBmId) {
    return {
      ok: false,
      message: 'missing_owner_bm_id: TKQC thiếu owner_business.id/bm để gửi acting_brand_id',
    };
  }

  const role = typeof values.role === 'string' && values.role in PARTNER_TASKS ? values.role : 'admin';
  const tasks = PARTNER_TASKS[role]!;

  const { validIds: partnerBmIds, skipped: skippedPartnerBmIds } = parsePartnerBmIds(values.bmIds);

  if (partnerBmIds.length === 0) {
    return {
      ok: false,
      message: `Không có BM đích hợp lệ để share · bỏ qua ${skippedPartnerBmIds.length}`,
    };
  }

  const successPartnerBmIds: string[] = [];
  const failedPartnerBmIds: Array<{ bmId: string; reason: string }> = [];
  const appliedDelaysMs: number[] = [];

  for (const [i, partnerBmId] of partnerBmIds.entries()) {
    const res = await shareOnePartner(adId, ownerBmId, partnerBmId, tasks);
    if (res.ok) successPartnerBmIds.push(partnerBmId);
    else failedPartnerBmIds.push({ bmId: partnerBmId, reason: res.message });

    // Wait a random anti-rate-limit delay between partner BM requests inside
    // the same account. runBatch already owns the inter-account delay.
    if (i < partnerBmIds.length - 1) {
      const delayMs = randomPartnerDelayMs();
      appliedDelaysMs.push(delayMs);
      await wait(delayMs);
    }
  }

  const messageParts = [
    `Share ${successPartnerBmIds.length}/${partnerBmIds.length} đối tác`,
    `ownerBm ${ownerBmId}`,
    `role ${role}`,
    `delay random 1-3s${appliedDelaysMs.length > 0 ? ` (${appliedDelaysMs.join(',')}ms)` : ''}`,
    `bỏ qua ${skippedPartnerBmIds.length}`,
  ];
  if (failedPartnerBmIds.length > 0) {
    messageParts.push(
      `lỗi: ${failedPartnerBmIds.map((item) => `${item.bmId}: ${item.reason}`).join('; ')}`
    );
  }

  return {
    ok: failedPartnerBmIds.length === 0,
    message: messageParts.join(' · '),
  };
};
