import { graph } from '../fb-graph';
import { isGraphError } from '../types';
import type { AdAccount } from '../../features/adaccounts';
import type { ToolRunner } from './index';

interface PartnerAgency {
  id?: string;
  name?: string;
  access_status?: string;
  permitted_roles?: string[];
  permitted_tasks?: string[];
}

interface PartnerListResponse {
  data?: PartnerAgency[];
}

interface DeleteAgencyResponse {
  success?: boolean;
}

interface ParsedManualIds {
  validIds: string[];
  skipped: Array<{ bmId: string; reason: string }>;
}

const VALID_BM_ID_RE = /^\d{6,}$/;
const PARTNER_FIELDS = 'id,name,access_status,permitted_roles,permitted_tasks';

function bareAccountId(account: AdAccount): string {
  if (account.account_id) return account.account_id;
  return account.id.startsWith('act_') ? account.id.slice(4) : account.id;
}

function ownerBusinessId(account: AdAccount): string | null {
  return account.owner_business?.id ?? account.bm ?? null;
}

function splitManualIds(value: unknown): string[] {
  if (typeof value !== 'string') return [];
  return value
    .split(/[\s,]+/)
    .map((id) => id.trim())
    .filter(Boolean);
}

function parseManualIds(value: unknown): ParsedManualIds {
  const seen = new Set<string>();
  const validIds: string[] = [];
  const skipped: Array<{ bmId: string; reason: string }> = [];

  for (const id of splitManualIds(value)) {
    if (!VALID_BM_ID_RE.test(id)) {
      skipped.push({ bmId: id, reason: 'invalid_or_duplicate_input' });
      continue;
    }
    if (seen.has(id)) {
      skipped.push({ bmId: id, reason: 'invalid_or_duplicate_input' });
      continue;
    }
    seen.add(id);
    validIds.push(id);
  }

  return { validIds, skipped };
}

function unique(ids: string[]): string[] {
  return Array.from(new Set(ids));
}

function randomPartnerDeleteDelayMs(): number {
  return 1000 + Math.floor(Math.random() * 2001);
}

function wait(ms: number): Promise<void> {
  return new Promise((resolve) => window.setTimeout(resolve, ms));
}

async function listPartners(adId: string): Promise<PartnerAgency[] | { error: true; message: string }> {
  const res = await graph<PartnerListResponse>(`/act_${adId}/agencies`, {
    method: 'GET',
    tokenPurpose: 'businessManagerAction',
    version: 'v24.0',
    params: {
      fields: PARTNER_FIELDS,
      limit: 500,
    },
  });

  if (isGraphError(res)) return { error: true, message: res.message };
  return res.data ?? [];
}

async function removeOnePartner(
  adId: string,
  ownerBmId: string,
  partnerBmId: string
): Promise<{ ok: boolean; message: string }> {
  const res = await graph<DeleteAgencyResponse>(`/act_${adId}/agencies`, {
    method: 'DELETE',
    tokenPurpose: 'businessManagerAction',
    version: 'v24.0',
    params: {
      method: 'delete',
      accountId: adId,
      acting_brand_id: ownerBmId,
      business: partnerBmId,
    },
  });

  if (isGraphError(res)) return { ok: false, message: res.message };
  if (res.success === true) return { ok: true, message: 'success' };
  return { ok: false, message: 'Graph không trả success=true' };
}

export const removePartnerAccount: ToolRunner = async (account, values) => {
  const adId = bareAccountId(account);
  const ownerBmId = ownerBusinessId(account);
  const mode = typeof values.mode === 'string' ? values.mode : 'select';

  if (!ownerBmId) {
    return { ok: false, message: 'missing_owner_bm_id: TKQC thiếu owner_business.id/bm để gửi acting_brand_id' };
  }

  if (mode === 'select') {
    return {
      ok: false,
      message: 'Chế độ Chọn từ danh sách chưa có UI map đối tác theo từng TKQC; dùng Nhập thủ công hoặc Xóa tất cả.',
    };
  }

  const skippedPartnerBmIds: Array<{ bmId: string; reason: string }> = [];
  const warnings: Array<{ bmId: string; reason: string }> = [];
  let targetPartnerIds: string[] = [];

  if (mode === 'all') {
    if (values.confirmAll !== true) {
      return { ok: false, message: 'Cần tick xác nhận trước khi chạy chế độ Xóa tất cả đối tác.' };
    }

    const partners = await listPartners(adId);
    if ('error' in partners) return { ok: false, message: `cannot_load_partner_list: ${partners.message}` };

    targetPartnerIds = unique(partners.map((partner) => partner.id ?? '').filter(Boolean));
    if (targetPartnerIds.length === 0) {
      return { ok: true, message: 'Không có đối tác để xóa' };
    }
  } else if (mode === 'manual') {
    const parsed = parseManualIds(values.bmIds);
    targetPartnerIds = parsed.validIds;
    skippedPartnerBmIds.push(...parsed.skipped);

    if (targetPartnerIds.length === 0) {
      return {
        ok: false,
        message: `Không có BM ID hợp lệ để xóa · bỏ qua ${skippedPartnerBmIds.length}`,
      };
    }
  } else {
    return { ok: false, message: `Chế độ xóa đối tác không hợp lệ: ${mode}` };
  }

  const successPartnerBmIds: string[] = [];
  const failedPartnerBmIds: Array<{ bmId: string; reason: string }> = [];

  for (const [index, partnerBmId] of targetPartnerIds.entries()) {
    const res = await removeOnePartner(adId, ownerBmId, partnerBmId);
    if (res.ok) successPartnerBmIds.push(partnerBmId);
    else failedPartnerBmIds.push({ bmId: partnerBmId, reason: res.message });

    if (index < targetPartnerIds.length - 1) await wait(randomPartnerDeleteDelayMs());
  }

  const messageParts = [
    `Xóa ${successPartnerBmIds.length}/${targetPartnerIds.length} đối tác`,
    `ownerBm ${ownerBmId}`,
    `mode ${mode}`,
    `bỏ qua ${skippedPartnerBmIds.length}`,
  ];
  if (warnings.length > 0) messageParts.push(`cảnh báo ${warnings.length}`);
  if (failedPartnerBmIds.length > 0) {
    messageParts.push(`lỗi: ${failedPartnerBmIds.map((item) => `${item.bmId}: ${item.reason}`).join('; ')}`);
  }

  return { ok: failedPartnerBmIds.length === 0, message: messageParts.join(' · ') };
};
