import { graph } from '../fb-graph';
import { isGraphError } from '../types';
import type { AdAccount } from '../../features/adaccounts';
import type { ToolRunner } from './index';
import { bareAccountId, wait } from './remove-user-helpers';

const VALID_ROLES = ['admin', 'advertiser', 'analyst'] as const;
type AddUserRole = (typeof VALID_ROLES)[number];

const ROLE_IDS: Record<AddUserRole, number> = {
  admin: 1001,
  advertiser: 1002,
  analyst: 1003,
};

const UID_RE = /^\d{6,}$/;
const MIN_UID_DELAY_MS = 1000;
const MAX_UID_DELAY_MS = 3000;

interface AddUserResponse {
  success?: boolean;
}

interface ParsedUids {
  valid: string[];
  skipped: string[];
}

function accountId(account: AdAccount): string {
  return bareAccountId(account.account_id || account.id);
}

function parseUidList(value: unknown): ParsedUids {
  if (typeof value !== 'string') return { valid: [], skipped: [] };

  const valid: string[] = [];
  const skipped: string[] = [];
  const seen = new Set<string>();
  const tokens = value
    .split(/[\r\n,]+/)
    .map((token) => token.trim())
    .filter(Boolean);

  for (const token of tokens) {
    if (!UID_RE.test(token)) {
      skipped.push(`${token}:invalid`);
      continue;
    }
    if (seen.has(token)) {
      skipped.push(`${token}:duplicate`);
      continue;
    }
    seen.add(token);
    valid.push(token);
  }

  return { valid, skipped };
}

function randomUidDelayMs(): number {
  return MIN_UID_DELAY_MS + Math.floor(Math.random() * (MAX_UID_DELAY_MS - MIN_UID_DELAY_MS + 1));
}

async function addOneUser(adId: string, uid: string, roleId: number): Promise<{ ok: boolean; message: string }> {
  const res = await graph<AddUserResponse>(`/act_${adId}/users`, {
    method: 'POST',
    tokenPurpose: 'powerEditorAction',
    params: {
      role: roleId,
      uid,
    },
  });

  if (isGraphError(res)) return { ok: false, message: res.message };
  if (res.success === true) return { ok: true, message: 'OK' };
  return { ok: false, message: 'Graph không trả success=true; kết quả thêm admin không xác định' };
}

export const addUser: ToolRunner = async (account, values) => {
  const adId = accountId(account);
  const roleRaw = typeof values.role === 'string' ? values.role : 'admin';
  const role: AddUserRole | null = (VALID_ROLES as readonly string[]).includes(roleRaw) ? (roleRaw as AddUserRole) : null;
  if (!role) {
    return { ok: false, message: `invalid_role: Vai trò không hợp lệ "${roleRaw}"; chọn admin/advertiser/analyst` };
  }

  const { valid: uids, skipped } = parseUidList(values.uidList);
  if (uids.length === 0) {
    const skippedText = skipped.length > 0 ? ` · bỏ qua ${skipped.length} token (${skipped.slice(0, 3).join(', ')})` : '';
    return { ok: false, message: `no_valid_uid: Cần nhập ít nhất 1 ID người dùng hợp lệ${skippedText}` };
  }

  const roleId = ROLE_IDS[role];
  const successes: string[] = [];
  const failures: string[] = [];

  for (const [uidIndex, uid] of uids.entries()) {
    if (uidIndex > 0) await wait(randomUidDelayMs());
    const result = await addOneUser(adId, uid, roleId);
    if (result.ok) {
      successes.push(uid);
    } else {
      failures.push(`${uid}: ${result.message}`);
    }
  }

  const skippedText = skipped.length > 0 ? ` · bỏ qua ${skipped.length}` : '';
  if (failures.length === 0) {
    return { ok: true, message: `OK add-user ${role} (${roleId}) · thành công ${successes.length}/${uids.length}${skippedText}` };
  }

  const failurePreview = failures.slice(0, 3).join(' | ');
  if (successes.length > 0) {
    return {
      ok: false,
      message: `PARTIAL add-user ${role} (${roleId}) · thành công ${successes.length}/${uids.length}, lỗi ${failures.length}${skippedText} · ${failurePreview}`,
    };
  }

  return {
    ok: false,
    message: `FAIL add-user ${role} (${roleId}) · lỗi ${failures.length}/${uids.length}${skippedText} · ${failurePreview}`,
  };
};
