<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import {
  Avatar,
  AvatarFallback,
  Badge,
  Button,
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
  Skeleton,
} from '@mf2/shared-ui';
import { Icon } from '@mf2/shared-ui/icons';
import { toast } from '@mf2/shared-ui/sonner';
import { getCurrentFacebookUserId, runAdAccountAdminAction, type AdAccountAdminAction } from '../api/adaccount-admin-actions';
import type { AdAccount, AdAccountAdminUser } from '../types/account-list.types';

const props = defineProps<{
  open: boolean;
  account: AdAccount | null;
}>();

const emit = defineEmits<{
  (event: 'update:open', value: boolean): void;
  (event: 'patched', accountId: string, patch: Partial<AdAccount>): void;
}>();

const search = ref('');
const currentUserId = ref<string | undefined>();
const loadingCurrentUser = ref(false);
const runningKey = ref<string | null>(null);

const users = computed<AdAccountAdminUser[]>(() => props.account?.adminUsers ?? []);

const filteredUsers = computed<AdAccountAdminUser[]>(() => {
  const keyword = search.value.trim().toLowerCase();
  if (!keyword) return users.value;
  return users.value.filter((user) =>
    `${user.name ?? ''} ${user.id}`.toLowerCase().includes(keyword)
  );
});

watch(
  () => props.open,
  async (open) => {
    if (!open) {
      search.value = '';
      runningKey.value = null;
      loadingCurrentUser.value = false;
      return;
    }
    loadingCurrentUser.value = true;
    currentUserId.value = await getCurrentFacebookUserId();
    loadingCurrentUser.value = false;
  }
);

function initials(name: string | undefined, id: string): string {
  const source = (name || id).trim();
  const parts = source.split(/\s+/).filter(Boolean);
  if (parts.length >= 2) return `${parts[0]?.[0] ?? ''}${parts[parts.length - 1]?.[0] ?? ''}`.toUpperCase();
  return source.slice(0, 2).toUpperCase();
}

function roleBadgeClass(role: AdAccountAdminUser['role']): string {
  if (role === 'admin') return 'border-[#BFD8CC] bg-[#F8FFFA] text-[#2F7D36]';
  if (role === 'advertiser') return 'border-[#CFE2D8] bg-[#F3F7F5] text-[#3F6B58]';
  if (role === 'analyst') return 'border-[#E7DAC2] bg-[#FFF9ED] text-[#9A6A21]';
  return 'border-[#DDE5E1] bg-[#F6FAF8] text-[#5E6360]';
}

function actionLabel(action: AdAccountAdminAction): string {
  if (action === 'promote') return 'Đang nâng quyền...';
  if (action === 'demote') return 'Đang hạ quyền...';
  return 'Đang xóa...';
}

async function runAction(user: AdAccountAdminUser, action: AdAccountAdminAction): Promise<void> {
  if (!props.account) return;
  const key = `${user.id}:${action}`;
  runningKey.value = key;
  try {
    const result = await runAdAccountAdminAction(props.account, user, action);
    if (result.patch) emit('patched', props.account.id, result.patch);
    toast.success(result.message);
  } catch (error) {
    toast.error(error instanceof Error ? error.message : String(error));
  } finally {
    runningKey.value = null;
  }
}

function isRunning(user: AdAccountAdminUser, action: AdAccountAdminAction): boolean {
  return runningKey.value === `${user.id}:${action}`;
}
</script>

<template>
  <Dialog :open="open" @update:open="emit('update:open', $event)">
    <DialogContent
      class="max-h-[88vh] max-w-[min(920px,calc(100vw-48px))] overflow-hidden rounded-[22px] border border-[#DCEBE3] bg-[#EEF6F1] p-0 text-[#1F2A24] shadow-[0_24px_70px_rgba(31,42,36,0.18)]"
    >
      <div class="flex h-[min(88vh,680px)] min-h-0 flex-col">
        <DialogHeader class="border-b border-[#DCEBE3] bg-[#F8FFFA]/80 px-5 py-4 pr-12">
          <DialogTitle class="flex items-center gap-2 text-sm font-normal tracking-[-0.02em] text-[#17211B]">
            <span class="grid size-8 place-items-center rounded-full bg-white text-[#3C9944] shadow-sm ring-1 ring-[#DCEBE3]">
              <Icon name="users" :size="15" />
            </span>
            Quản trị viên TKQC
          </DialogTitle>
          <DialogDescription class="pl-10 text-xs text-[#6E7772]">
            <span class="font-medium text-[#17211B]">{{ account?.name || 'TKQC' }}</span>
            <span v-if="account?.account_id || account?.id"> · {{ account?.account_id || account?.id }}</span>
          </DialogDescription>
        </DialogHeader>

        <div class="relative px-5 py-4">
          <Icon name="search" class="pointer-events-none absolute left-9 top-1/2 size-4 -translate-y-1/2 text-[#8A948E]" />
          <input
            v-model="search"
            class="h-10 w-full rounded-full border border-[#DCEBE3] bg-white/85 pl-10 pr-4 text-sm text-[#17211B] shadow-sm outline-none transition focus:border-[#BFD8CC] focus:ring-2 focus:ring-[#73C258]/20"
            placeholder="Tìm theo tên hoặc UID..."
          />
        </div>

        <div v-if="loadingCurrentUser" class="space-y-3 px-5 pb-5">
          <div v-for="index in 3" :key="index" class="flex items-center gap-3 rounded-[18px] bg-white p-3 shadow-[0_12px_28px_rgba(31,42,36,0.06)] ring-1 ring-[#DCEBE3]">
            <Skeleton class="size-11 shrink-0 rounded-full" />
            <div class="min-w-0 flex-1 space-y-2">
              <Skeleton class="h-3 w-36 rounded-full" />
              <Skeleton class="h-3 w-52 rounded-full" />
            </div>
            <Skeleton class="h-7 w-24 rounded-full" />
            <Skeleton class="size-8 rounded-full" />
          </div>
        </div>

        <div v-else class="min-h-0 flex-1 space-y-3 overflow-y-auto px-5 pb-5">
        <div
          v-for="user in filteredUsers"
          :key="user.id"
          class="flex items-center gap-3 rounded-[18px] bg-white p-3 shadow-[0_12px_28px_rgba(31,42,36,0.06)] ring-1 ring-[#DCEBE3] transition hover:bg-[#F8FFFA] hover:ring-[#BFD8CC]"
          :class="currentUserId === user.id ? 'bg-[#F8FFFA] ring-[#BFD8CC]' : ''"
        >
          <Avatar class="size-11 rounded-full">
            <AvatarFallback class="rounded-full bg-[linear-gradient(270deg,#73C258_0%,#3C9944_100%)] text-sm font-semibold text-white">
              {{ initials(user.name, user.id) }}
            </AvatarFallback>
          </Avatar>

          <div class="min-w-0 flex-1">
            <div class="flex flex-wrap items-center gap-2">
              <p class="truncate text-sm font-medium tracking-[-0.02em] text-[#17211B]">{{ user.name || 'Không rõ tên' }}</p>
              <Badge v-if="currentUserId === user.id" class="border-[#3C9944] bg-[#3C9944] px-1.5 py-0 text-[10px] text-white">BẠN</Badge>
            </div>
            <div class="mt-1 flex items-center gap-1.5 text-xs text-[#7A8580]">
              <Icon name="hash" :size="12" />
              <span>{{ user.id }}</span>
            </div>
          </div>

          <Badge class="shrink-0 px-2.5 py-1 text-xs font-medium" :class="roleBadgeClass(user.role)">
            {{ user.roleLabel }}
          </Badge>

          <DropdownMenu>
            <DropdownMenuTrigger as-child>
              <Button
                variant="secondary"
                size="icon"
                class="size-8 shrink-0 rounded-full bg-white text-[#4C5A52] shadow-sm ring-1 ring-[#DCEBE3] hover:bg-[#F8FFFA] hover:text-[#3C9944]"
                :disabled="Boolean(runningKey)"
              >
                <Icon name="more-vertical" :size="14" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" class="w-64 rounded-[14px] border border-[#BFD8CC] bg-[#F3F7F5] p-1.5 shadow-[0_14px_36px_rgba(31,42,36,0.14)]">
              <DropdownMenuItem
                class="h-10 cursor-pointer gap-2.5 rounded-[10px] text-sm text-[#4C5A52]"
                :disabled="user.role === 'admin' || isRunning(user, 'promote')"
                @select="runAction(user, 'promote')"
              >
                <Icon v-if="isRunning(user, 'promote')" name="loader-2" class="size-4 animate-spin text-[#3C9944]" />
                <Icon v-else name="arrow-up" class="size-4 text-[#3C9944]" />
                {{ isRunning(user, 'promote') ? actionLabel('promote') : 'Nâng quyền' }}
              </DropdownMenuItem>
              <DropdownMenuItem
                class="h-10 cursor-pointer gap-2.5 rounded-[10px] text-sm text-[#4C5A52]"
                :disabled="user.role === 'analyst' || isRunning(user, 'demote')"
                @select="runAction(user, 'demote')"
              >
                <Icon v-if="isRunning(user, 'demote')" name="loader-2" class="size-4 animate-spin text-[#3C9944]" />
                <Icon v-else name="arrow-down" class="size-4 text-[#3C9944]" />
                {{ isRunning(user, 'demote') ? actionLabel('demote') : 'Hạ quyền' }}
              </DropdownMenuItem>
              <DropdownMenuSeparator />
              <DropdownMenuItem
                variant="destructive"
                class="h-10 cursor-pointer gap-2.5 rounded-[10px] text-sm"
                :disabled="isRunning(user, 'remove')"
                @select="runAction(user, 'remove')"
              >
                <Icon v-if="isRunning(user, 'remove')" name="loader-2" class="size-4 animate-spin text-red-500" />
                <Icon v-else name="user" class="size-4 text-red-500" />
                {{ isRunning(user, 'remove') ? actionLabel('remove') : 'Xóa quản trị viên' }}
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>

        <div v-if="filteredUsers.length === 0" class="rounded-[18px] border border-dashed border-[#BFD8CC] bg-white/70 p-8 text-center text-sm text-[#6E7772]">
          Không tìm thấy quản trị viên phù hợp.
        </div>
        </div>
      </div>
    </DialogContent>
  </Dialog>
</template>
