import { graph, graphql } from '../fb-graph';
import { getToken } from '../fb-token';
import { isGraphError } from '../types';
import type { AdAccount, CardData } from '../../features/adaccounts';
import type { ToolRunner } from './index';

const DELETE_CARD_DOC_ID = '9195168280589012';
const UNKNOWN_CREDENTIAL_ID = 'Unknown';
const MIN_CARD_DELETE_DELAY_MS = 1_000;
const MAX_CARD_DELETE_DELAY_MS = 3_000;

interface DeleteCardResponse {
  data?: unknown;
}

interface CreditCardNode {
  credential_id?: string;
  display_string?: string;
}

interface PaymentMethodsResponse {
  all_payment_methods?: {
    pm_credit_card?: {
      data?: CreditCardNode[];
    };
  };
  funding_source_details?: {
    display_string?: string;
    type?: string;
  };
}

interface DeleteCardOutcome {
  card: CardData;
  ok: boolean;
  reason?: string;
}

function bareId(id: string): string {
  return id.startsWith('act_') ? id.slice(4) : id;
}

function wait(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function randomCardDeleteDelayMs(): number {
  return Math.floor(Math.random() * (MAX_CARD_DELETE_DELAY_MS - MIN_CARD_DELETE_DELAY_MS + 1)) + MIN_CARD_DELETE_DELAY_MS;
}

function parseCardSuffixes(value: unknown): string[] {
  const text = String(value ?? '');
  const suffixes = text.match(/\d{4}/g) ?? [];
  return [...new Set(suffixes)];
}

function parseCreditCards(cards: CreditCardNode[] | undefined): CardData[] {
  return (cards ?? []).map((card) => {
    const displayString = card.display_string ?? '';
    return {
      display: displayString.match(/\d+/)?.[0] || UNKNOWN_CREDENTIAL_ID,
      type: displayString.toLowerCase().match(/[^\d\W]+/)?.[0],
      credential_id: card.credential_id || UNKNOWN_CREDENTIAL_ID,
    };
  });
}

async function fetchCardData(adId: string): Promise<CardData[]> {
  const res = await graph<PaymentMethodsResponse>(
    `/act_${adId}`,
    {
      method: 'GET',
      params: {
        fields: 'all_payment_methods{pm_credit_card{credential_id,display_string}},funding_source_details{display_string,type}',
      },
      tokenPurpose: 'readGraph',
    }
  );

  if (isGraphError(res)) throw new Error(res.message);
  return parseCreditCards(res.all_payment_methods?.pm_credit_card?.data);
}

async function resolveCardData(account: AdAccount, adId: string): Promise<CardData[]> {
  // Always fetch fresh payment methods before a destructive delete. Row/card cache
  // can be stale or incomplete; using it alone can show a success toast without
  // ever sending the delete mutation for accounts whose cached `card_data` is empty.
  const freshCards = await fetchCardData(adId);
  if (freshCards.length > 0) return freshCards;
  return account.card_data ?? [];
}

function isDeletableCard(card: CardData): boolean {
  return Boolean(card.credential_id && card.credential_id !== UNKNOWN_CREDENTIAL_ID);
}

function selectCards(cards: CardData[], mode: string, suffixes: string[]): CardData[] {
  const deletableCards = cards.filter(isDeletableCard);
  if (mode === 'card_list') return deletableCards.filter((card) => suffixes.includes(card.display));
  return deletableCards;
}

async function deleteOneCard(adId: string, credentialId: string, actorId: string): Promise<{ ok: boolean; reason?: string }> {
  const res = await graphql<DeleteCardResponse>(
    {
      doc_id: DELETE_CARD_DOC_ID,
      variables: JSON.stringify({
        input: {
          payment_account_id: adId,
          payment_method_id: credentialId,
          actor_id: actorId,
        },
      }),
    },
    'www'
  );

  if (isGraphError(res)) return { ok: false, reason: res.message };
  return { ok: true };
}

function buildPatch(baseCards: CardData[], outcomes: DeleteCardOutcome[]): Partial<AdAccount> | undefined {
  const deletedCredentialIds = new Set(
    outcomes.filter((outcome) => outcome.ok).map((outcome) => outcome.card.credential_id)
  );
  if (deletedCredentialIds.size === 0) return undefined;

  const card_data = baseCards.filter((card) => !deletedCredentialIds.has(card.credential_id));
  return {
    card_data,
    ...(card_data.length === 0 ? { payment: undefined, paymentStatus: 'unavailable' as const } : {}),
  };
}

function summarize(outcomes: DeleteCardOutcome[]): { ok: boolean; message: string } {
  const success = outcomes.filter((outcome) => outcome.ok);
  const failed = outcomes.filter((outcome) => !outcome.ok);
  const successLabels = success.map((outcome) => outcome.card.display).join(', ');

  if (success.length > 0 && failed.length === 0) {
    return { ok: true, message: `Đã xóa ${success.length} thẻ${successLabels ? ` (${successLabels})` : ''}` };
  }

  const failedLabels = failed
    .map((outcome) => `${outcome.card.display}: ${outcome.reason ?? 'không rõ lỗi'}`)
    .join('; ');

  if (success.length > 0) {
    return {
      ok: false,
      message: `PARTIAL — đã xóa ${success.length} thẻ${successLabels ? ` (${successLabels})` : ''}; lỗi ${failed.length} thẻ: ${failedLabels}`,
    };
  }

  return { ok: false, message: `Không xóa được thẻ nào: ${failedLabels || 'không rõ lỗi'}` };
}

export const deleteCard: ToolRunner = async (account, values) => {
  const mode = String(values.mode ?? 'all');
  if (mode !== 'all' && mode !== 'card_list') {
    return { ok: false, message: 'Chế độ xóa thẻ không hợp lệ' };
  }

  if (values.confirm !== true) {
    return { ok: false, message: 'Cần bật xác nhận trước khi xóa thẻ thanh toán' };
  }

  const adId = bareId(account.id);
  if (!adId) return { ok: false, message: 'Thiếu ID tài khoản' };

  const suffixes = parseCardSuffixes(values.cardNumbers);
  if (mode === 'card_list' && suffixes.length === 0) {
    return { ok: false, message: 'Vui lòng nhập ít nhất một mã 4 số cuối thẻ cần xóa' };
  }

  const cards = await resolveCardData(account, adId);
  const cardsToDelete = selectCards(cards, mode, suffixes);
  if (cardsToDelete.length === 0) {
    return {
      ok: false,
      message: mode === 'card_list'
        ? `Không tìm thấy thẻ khớp 4 số cuối: ${suffixes.join(', ')}`
        : 'Không tìm thấy thẻ có credential_id',
    };
  }

  const { user_id } = await getToken();
  const outcomes: DeleteCardOutcome[] = [];

  for (const [i, card] of cardsToDelete.entries()) {
    if (i > 0) await wait(randomCardDeleteDelayMs());
    const result = await deleteOneCard(adId, card.credential_id, user_id);
    outcomes.push({ card, ok: result.ok, reason: result.reason });
  }

  const summary = summarize(outcomes);
  return {
    ok: summary.ok,
    message: summary.message,
    patch: buildPatch(cards, outcomes),
  };
};
