import { graph } from '../fb-graph';
import { isGraphError } from '../types';
import type { ToolRunner } from './index';

interface AddBmLine2Response {
  access_status?: string;
  success?: boolean;
}

interface ParsedBmIds {
  validIds: string[];
  invalidCount: number;
  duplicateCount: number;
}

function bareId(id: string): string {
  return id.startsWith('act_') ? id.slice(4) : id;
}

function cleanNumericId(value: unknown): string {
  return String(value ?? '').trim().replace(/^act_/i, '');
}

function parseBmIds(value: unknown): ParsedBmIds {
  const seen = new Set<string>();
  const validIds: string[] = [];
  let invalidCount = 0;
  let duplicateCount = 0;

  for (const rawToken of String(value ?? '').split(/[\s,]+/)) {
    const bmId = cleanNumericId(rawToken);
    if (!bmId) continue;

    if (!/^\d{6,}$/.test(bmId)) {
      invalidCount += 1;
      continue;
    }

    if (seen.has(bmId)) {
      duplicateCount += 1;
      continue;
    }

    seen.add(bmId);
    validIds.push(bmId);
  }

  return { validIds, invalidCount, duplicateCount };
}

function randomDelayMs(): number {
  return 1000 + Math.floor(Math.random() * 2001);
}

function wait(ms: number): Promise<void> {
  return new Promise((resolve) => globalThis.setTimeout(resolve, ms));
}

async function addAccountToBm(adId: string, bmId: string): Promise<AddBmLine2Response> {
  const res = await graph<AddBmLine2Response>(`/${bmId}/client_ad_accounts`, {
    method: 'POST',
    params: { __cppo: 1 },
    tokenPurpose: 'businessManagerAction',
    body: {
      _reqName: 'object:brand/client_ad_accounts',
      _reqSrc: 'AdAccountActions.brands',
      access_type: 'AGENCY',
      adaccount_id: `act_${adId}`,
      method: 'post',
      'permitted_tasks[0]': 'ADVERTISE',
      'permitted_tasks[1]': 'ANALYZE',
      'permitted_tasks[2]': 'DRAFT',
      'permitted_tasks[3]': 'MANAGE',
      pretty: 0,
      suppress_http_code: 1,
    },
  });

  if (isGraphError(res)) throw new Error(res.message);
  return res;
}

function isSuccessfulAddBmResponse(res: AddBmLine2Response): boolean {
  const status = String(res.access_status ?? '').toUpperCase();
  return status === 'PENDING' || status === 'CONFIRMED' || res.success === true;
}

export const addBmLine2: ToolRunner = async (account, values) => {
  const { validIds: bmIds, invalidCount, duplicateCount } = parseBmIds(values.bmIds ?? values.bmId);
  if (bmIds.length === 0) {
    return { ok: false, message: 'Vui lòng nhập ít nhất 1 ID BM dòng 2 hợp lệ' };
  }

  const adId = bareId(account.id || account.account_id || '');
  if (!adId) return { ok: false, message: 'Thiếu ID tài khoản quảng cáo' };

  const successes: string[] = [];
  const failures: string[] = [];

  for (const [index, bmId] of bmIds.entries()) {

    try {
      const res = await addAccountToBm(adId, bmId);
      const status = String(res.access_status ?? '').toUpperCase();
      if (isSuccessfulAddBmResponse(res)) {
        successes.push(`${bmId}${status ? ` (${status})` : ''}`);
      } else {
        failures.push(`${bmId}: FB chưa xác nhận ${JSON.stringify(res)}`);
      }
    } catch (error) {
      failures.push(`${bmId}: ${error instanceof Error ? error.message : String(error)}`);
    }

    if (index < bmIds.length - 1) {
      await wait(randomDelayMs());
    }
  }

  const skippedParts = [
    invalidCount > 0 ? `${invalidCount} ID không hợp lệ` : '',
    duplicateCount > 0 ? `${duplicateCount} ID trùng` : '',
  ].filter(Boolean);
  const skippedSuffix = skippedParts.length > 0 ? `; bỏ qua ${skippedParts.join(', ')}` : '';

  if (failures.length > 0) {
    return {
      ok: false,
      message: `PARTIAL thêm dòng 2 BM: thành công ${successes.length}/${bmIds.length}${skippedSuffix}; lỗi ${failures.join('; ')}`,
    };
  }

  return {
    ok: true,
    message: `Đã thêm TKQC vào ${successes.length} BM dòng 2: ${successes.join(', ')}${skippedSuffix}`,
  };
};
