import { graphql, responseHasMarker } from '../fb-graph';
import { getToken } from '../fb-token';
import { isGraphError } from '../types';
import type { ToolRunner } from './index';

// Open (reactivate) / close (deactivate) an ad account.
// Uses internal Facebook GraphQL (API 1) only.

const CLOSE_DOC_ID = '9895135750555877'; // BizKitSettingsDeactivateAdAccountMutation
const OPEN_DOC_ID = '9984888131552276';  // useBillingReactivateAdAccountMutation

function bareId(id: string): string {
  return id.startsWith('act_') ? id.slice(4) : id;
}

async function doCloseGraphql(adId: string): Promise<{ ok: boolean; message?: string }> {
  const res = await graphql<{ data?: { business_settings_deactivate_ad_account?: unknown } }>(
    {
      fb_api_req_friendly_name: 'BizKitSettingsDeactivateAdAccountMutation',
      doc_id: CLOSE_DOC_ID,
      variables: JSON.stringify({ adAccountID: adId }),
    },
    'business'
  );
  if (isGraphError(res)) return { ok: false, message: res.message };
  if (res?.data?.business_settings_deactivate_ad_account) return { ok: true };
  return { ok: false, message: 'GraphQL không xác nhận được đóng tài khoản' };
}

async function doOpenGraphql(adId: string): Promise<{ ok: boolean; message?: string }> {
  const { user_id } = await getToken();
  const res = await graphql(
    {
      fb_api_req_friendly_name: 'useBillingReactivateAdAccountMutation',
      doc_id: OPEN_DOC_ID,
      variables: JSON.stringify({
        input: {
          billable_account_payment_legacy_account_id: adId,
          actor_id: user_id,
          client_mutation_id: '1',
          logging_data: {},
          upl_logging_data: { wizard_name: 'REACTIVATE_AD_ACCOUNT' },
        },
      }),
    },
    'adsmanager'
  );
  if (isGraphError(res)) return { ok: false, message: res.message };
  if (responseHasMarker(res, 'ADMARKET_ACCOUNT_STATUS_ACTIVE')) return { ok: true };
  // No marker and no error → unconfirmed; report as failure (truthful-pessimistic).
  return { ok: false, message: 'GraphQL không xác nhận được mở tài khoản' };
}

// --- Runner ---

export const openCloseAccount: ToolRunner = async (account, values) => {
  const mode = String(values.mode ?? 'close');
  if (mode !== 'open' && mode !== 'close') {
    return { ok: false, message: 'Mode không hợp lệ (phải là open hoặc close)' };
  }

  const adId = bareId(account.id);
  if (!adId) return { ok: false, message: 'Thiếu ID tài khoản' };

  if (mode === 'close') {
    const r = await doCloseGraphql(adId);
    if (!r.ok) return { ok: false, message: r.message ?? 'Đóng tài khoản thất bại' };
    return { ok: true, message: 'Đã đóng tài khoản (GraphQL)', patch: { status: 101 } };
  }

  // mode === 'open'
  const r = await doOpenGraphql(adId);
  if (!r.ok) return { ok: false, message: r.message ?? 'Mở tài khoản thất bại' };
  return { ok: true, message: 'Đã mở tài khoản (GraphQL)', patch: { status: 1 } };
};
