<script setup lang="ts">
import { computed, ref } from 'vue';
import {
  Button,
  Checkbox,
  Input,
  Label,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
  Switch,
  Textarea,
} from '@mf2/shared-ui/form-controls';
import { Popover, PopoverContent, PopoverTrigger, RadioGroup, RadioGroupItem, Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@mf2/shared-ui';
import { Icon } from '@mf2/shared-ui/icons';
import { useToolActionsContext } from '@/composables/tool-actions/tool-actions-context';
import type { ToolFieldSchema, ToolFunction } from '@/types/tool-action.types';

// Schema-driven config form, rendered inline as the expanded body of a tool
// card. Binds to this tool's own values (valuesFor) so the common "Bắt Đầu"
// button below the list can run it. Uses shared-ui (shadcn-vue) form components.
// State comes from the panel-provided tool-actions instance (TKQC, Page, …).
const props = withDefaults(defineProps<{
  fn: ToolFunction;
  selectedCount: number;
  showHeader?: boolean;
  variant?: 'default' | 'panel-two';
}>(), {
  showHeader: true,
  variant: 'default',
});

const { valuesFor } = useToolActionsContext();
// This card edits its own tool's values (independent per tool so several enabled
// tools can be configured before one shared run).
const formValues = valuesFor(props.fn);
const searchQueries = ref<Record<string, string>>({});
const searchableSelectOpen = ref<Record<string, boolean>>({});

const isChangeInfo = computed(() => props.fn.id === 'change-info');

function matchesCondition(condition: { key: string; equals: string }): boolean {
  return String(formValues[condition.key]) === condition.equals;
}

function conditionList(
  value: ToolFieldSchema['disabledWhen'] | ToolFieldSchema['enabledWhen']
): Array<{ key: string; equals: string }> {
  if (!value) return [];
  return Array.isArray(value) ? value : [value];
}

// A field with `showWhen` is hidden until the referenced field matches. Compare
// as strings so a switch-driven condition works too (switch stores a boolean, so
// `equals: 'true'` matches a toggled-on switch as well as a select option).
function isVisible(field: ToolFieldSchema): boolean {
  if (!field.showWhen) return true;
  return matchesCondition(field.showWhen);
}

function isDisabled(field: ToolFieldSchema): boolean {
  if (conditionList(field.disabledWhen).some(matchesCondition)) return true;
  if (conditionList(field.enabledWhen).some((condition) => !matchesCondition(condition))) return true;
  if (field.enabledWhenAny?.length && !field.enabledWhenAny.some(matchesCondition)) return true;
  return false;
}

function fieldId(field: ToolFieldSchema): string {
  return `fld-${props.fn.id}-${field.key}`;
}

function optionLabel(field: ToolFieldSchema): string {
  const value = String(formValues[field.key] ?? '');
  return field.options?.find((opt) => opt.value === value)?.label ?? value;
}

function filteredOptions(field: ToolFieldSchema): Array<{ value: string; label: string }> {
  const query = (searchQueries.value[field.key] ?? '').trim().toLowerCase();
  const options = field.options ?? [];
  if (!query) return options;
  return options.filter((opt) => `${opt.value} ${opt.label}`.toLowerCase().includes(query));
}

function selectOption(field: ToolFieldSchema, value: string): void {
  formValues[field.key] = value;
  searchQueries.value = { ...searchQueries.value, [field.key]: '' };
  searchableSelectOpen.value = { ...searchableSelectOpen.value, [field.key]: false };
}

function sectionSummary(field: ToolFieldSchema): string {
  if (field.summaryKey) {
    const value = formValues[field.summaryKey];
    if (typeof value === 'boolean') return value ? 'Đã chọn' : 'Không đổi';
    if (typeof value === 'string' && value.trim()) return value.trim();
  }
  return field.summaryText ?? '';
}

function cardIconClass(field: ToolFieldSchema): string {
  if (field.key === 'currencySection') return 'bg-[#FFF5E6] text-[#F59E0B]';
  if (field.key === 'businessInfoSection') return 'bg-[#EAF2FF] text-[#3B82F6]';
  if (field.key === 'timezoneSection') return 'bg-[#FFF0F6] text-[#EC4899]';
  return 'bg-[#EAF7F0] text-[#2E7D32]';
}

function sectionEnabled(field: ToolFieldSchema): boolean {
  return field.summaryKey ? formValues[field.summaryKey] === true : false;
}

function isBusinessInfoTitle(field: ToolFieldSchema): boolean {
  return field.key === 'businessInfoSection';
}

const businessInfoFields = computed(() =>
  props.fn.fields?.filter((field) => field.group === 'businessInfo' && isVisible(field)) ?? []
);

const topLevelFields = computed(() =>
  props.fn.fields?.filter((field) => isVisible(field) && !isBusinessInfoField(field)) ?? []
);

function isBusinessInfoField(field: ToolFieldSchema): boolean {
  return field.group === 'businessInfo';
}

// File inputs can't be two-way bound (the browser blocks setting .value), so we
// store the chosen file's name into this tool's values for feedback. The real
// File object is read by the runner once that tool is wired.
function onFileChange(key: string, event: Event): void {
  const file = (event.target as HTMLInputElement).files?.[0];
  if (file) formValues[key] = file;
  else formValues[key] = '';
}

function fileLabel(value: string | boolean | File | undefined): string {
  return value instanceof File ? value.name : String(value ?? '');
}
</script>

<template>
  <div v-if="props.showHeader" class="mb-3">
    <h4 class="text-sm font-semibold text-foreground">{{ fn.label }}</h4>
    <p class="mt-0.5 text-xs text-muted-foreground">Đã Chọn ({{ selectedCount }})</p>
  </div>

  <!-- Fields -->
  <TooltipProvider :delay-duration="200">
    <div :class="isChangeInfo ? 'space-y-2' : 'space-y-3'">
      <div
        v-if="!fn.fields || fn.fields.length === 0"
        class="flex items-start gap-3 rounded-[14px] border border-dashed border-[#BFD8CC] bg-[#F8FFFA] px-3 py-3 text-left"
        :class="props.variant === 'panel-two' ? 'border-[#BFD8CC] bg-white/90 shadow-[0_6px_18px_rgba(60,153,68,0.08)]' : ''"
      >
        <span class="grid size-7 shrink-0 place-items-center rounded-full border border-[#BFD8CC] bg-[#EAF7F0] text-[#3C9944] shadow-[0_3px_8px_rgba(60,153,68,0.10)]">
          <Icon name="check" :size="15" />
        </span>
        <span class="min-w-0 space-y-0.5">
          <span class="block text-xs font-semibold text-[#26352D]">Đã bật — không cần cấu hình</span>
          <span class="block text-[12px] leading-relaxed text-[#66736B]">
            Chức năng này sẽ tự động hoạt động trên các TKQC đã chọn khi chạy hành động.
          </span>
        </span>
      </div>

      <div
      v-for="field in topLevelFields"
      :key="field.key"
      class="space-y-1.5"
      :class="[
        props.variant === 'panel-two' ? (isChangeInfo ? 'rounded-[12px] bg-white px-2.5 py-2 ring-1 ring-[#E1ECE6]' : 'rounded-[16px] bg-white px-3 py-2.5 ring-1 ring-[#E1ECE6]') : '',
        field.type === 'section' && props.variant === 'panel-two' ? 'bg-transparent p-0 ring-0' : '',
        isDisabled(field) ? 'opacity-50' : '',
      ]"
    >
      <div
        v-if="field.type === 'section' && isBusinessInfoTitle(field)"
        class="space-y-2"
      >
        <div class="mb-2 flex items-center gap-2">
          <span class="grid size-8 shrink-0 place-items-center rounded-[10px]" :class="cardIconClass(field)">
            <Icon :name="field.sectionIcon ?? 'info'" :size="17" />
          </span>
          <span class="text-[12px] font-semibold text-[#26352D]">{{ field.sectionTitle ?? field.label }}</span>
        </div>
        <div class="grid grid-cols-1 gap-2 min-[420px]:grid-cols-2">
          <div
            v-for="child in businessInfoFields"
            :key="child.key"
            class="space-y-1.5 rounded-[12px] bg-[#F8FCFA] px-2.5 py-2"
            :class="child.fullWidth ? 'min-[420px]:col-span-2' : ''"
          >
            <Label
              :for="fieldId(child)"
              class="text-xs font-medium text-[#47534D]"
            >
              <span class="inline-flex items-center gap-1.5">
                <span>{{ child.label }}<span v-if="child.required" class="text-[#E5484D]">*</span></span>
                <Tooltip v-if="child.hint">
                  <TooltipTrigger as-child>
                    <Button
                      type="button"
                      variant="ghost"
                      size="icon-sm"
                      class="size-4 shrink-0 rounded-full p-0 text-[#7B8781] hover:bg-transparent hover:text-[#2E7D32]"
                      :aria-label="`${child.label}: ${child.hint}`"
                      @click.prevent
                    >
                      <Icon name="alert-circle" :size="13" />
                    </Button>
                  </TooltipTrigger>
                  <TooltipContent class="max-w-[240px] text-xs leading-relaxed">
                    {{ child.hint }}
                  </TooltipContent>
                </Tooltip>
              </span>
            </Label>
            <RadioGroup
              v-if="child.type === 'radio'"
              v-model="(formValues[child.key] as string)"
              class="flex flex-wrap items-center gap-x-6 gap-y-2"
            >
              <Label
                v-for="opt in child.options"
                :key="opt.value"
                class="flex cursor-pointer items-center gap-2 text-xs font-medium text-[#35433A]"
              >
                <RadioGroupItem :value="opt.value" />
                <span>{{ opt.label }}</span>
              </Label>
            </RadioGroup>
            <Popover v-else-if="child.type === 'searchable-select'" v-model:open="searchableSelectOpen[child.key]">
              <PopoverTrigger as-child>
                <Button
                  type="button"
                  variant="secondary"
                  class="h-9 w-full justify-between rounded-full border-0 bg-[#EEF5F1] px-3 text-left text-xs font-normal text-[#27332D] shadow-none ring-0 hover:bg-[#E6F0EA]"
                >
                  <span class="truncate">{{ optionLabel(child) || child.placeholder || 'Chọn...' }}</span>
                  <Icon name="chevron-down" :size="13" class="shrink-0 text-[#67736C]" />
                </Button>
              </PopoverTrigger>
              <PopoverContent class="w-[260px] rounded-[14px] border-[#BFD8CC] bg-[#F8FFFA] p-2 shadow-xl data-[state=closed]:hidden">
                <Input
                  v-model="searchQueries[child.key]"
                  :placeholder="child.optionSearchPlaceholder ?? 'Tìm kiếm...'"
                  class="mb-2 h-8 rounded-full border-0 bg-white px-3 text-xs text-[#27332D] shadow-none ring-1 ring-[#DCEBE3] placeholder:text-[#8B9690]"
                  autocomplete="off"
                />
                <div class="max-h-52 overflow-auto pr-1">
                  <Button
                    v-for="opt in filteredOptions(child)"
                    :key="opt.value"
                    type="button"
                    variant="ghost"
                    class="flex h-auto w-full items-center justify-between gap-2 rounded-[10px] px-2.5 py-1.5 text-left text-xs font-normal text-[#36433C] hover:bg-[#D8E9E1]"
                    @click="selectOption(child, opt.value)"
                  >
                    <span class="min-w-0 truncate">{{ opt.label }}</span>
                    <Icon v-if="formValues[child.key] === opt.value" name="check" :size="13" class="shrink-0 text-[#2E7D32]" />
                  </Button>
                  <p v-if="filteredOptions(child).length === 0" class="px-2 py-4 text-center text-xs text-[#7B8781]">Không có kết quả</p>
                </div>
              </PopoverContent>
            </Popover>
            <Input
              v-else
              :id="fieldId(child)"
              v-model="(formValues[child.key] as string)"
              :type="child.sensitive ? 'password' : child.type === 'number' ? 'number' : 'text'"
              :placeholder="child.placeholder"
              autocomplete="off"
              class="h-9 rounded-full border-0 bg-[#EEF5F1] px-3 text-xs text-[#27332D] shadow-none ring-0 placeholder:text-[#8B9690]"
            />
          </div>
        </div>
      </div>

      <Button
        v-else-if="field.type === 'section'"
        type="button"
        variant="ghost"
        class="flex h-auto w-full items-center justify-start gap-2 rounded-[14px] border border-[#E1ECE6] bg-white px-2.5 py-2 text-left shadow-[0_8px_18px_rgba(0,0,0,0.03)] transition hover:border-[#CFE2D8] hover:bg-[#FBFEFC]"
        @click="field.summaryKey ? formValues[field.summaryKey] = !sectionEnabled(field) : undefined"
      >
        <Checkbox
          v-if="field.summaryKey"
          :model-value="sectionEnabled(field)"
          class="shrink-0"
          @update:model-value="formValues[field.summaryKey] = Boolean($event)"
          @click.stop
        />
        <span class="grid size-8 shrink-0 place-items-center rounded-[10px]" :class="cardIconClass(field)">
          <Icon :name="field.sectionIcon ?? 'info'" :size="17" />
        </span>
        <span class="min-w-0 flex-1">
          <span class="block truncate text-[12px] font-semibold text-[#26352D]">{{ field.sectionTitle ?? field.label }}</span>
          <span class="mt-0.5 block truncate text-[11px] text-[#7A8580]">{{ sectionSummary(field) }}</span>
        </span>
        <Icon name="chevron-right" :size="14" class="shrink-0 text-[#58615C]" />
      </Button>

      <!-- Checkbox: explicit boolean choice that does not imply immediate action. -->
      <div v-else-if="field.type === 'checkbox'" class="flex items-center gap-2">
        <Checkbox
          :id="fieldId(field)"
          v-model="(formValues[field.key] as boolean)"
          :disabled="isDisabled(field)"
        />
        <Label
          :for="fieldId(field)"
          class="cursor-pointer text-xs"
          :class="props.variant === 'panel-two' ? 'font-medium text-[#47534D]' : ''"
        >
          {{ field.label }}
        </Label>
        <Tooltip v-if="field.hint">
          <TooltipTrigger as-child>
            <Button
              type="button"
              variant="ghost"
              size="icon-sm"
              class="size-4 shrink-0 rounded-full p-0 text-[#7B8781] hover:bg-transparent hover:text-[#2E7D32]"
              :aria-label="`${field.label}: ${field.hint}`"
              @click.prevent
            >
              <Icon name="alert-circle" :size="13" />
            </Button>
          </TooltipTrigger>
          <TooltipContent class="max-w-[240px] text-xs leading-relaxed">
            {{ field.hint }}
          </TooltipContent>
        </Tooltip>
      </div>

      <!-- Switch: label + toggle on one row -->
      <div v-else-if="field.type === 'switch'" class="space-y-1.5">
        <div class="flex items-center justify-between gap-2">
          <Label
            :for="fieldId(field)"
            class="text-xs"
            :class="props.variant === 'panel-two' ? 'font-medium text-[#47534D]' : ''"
          >
            {{ field.label }}
          </Label>
          <Switch
            :id="fieldId(field)"
            v-model="(formValues[field.key] as boolean)"
            :disabled="isDisabled(field)"
          />
        </div>
        <p v-if="field.description" class="text-[12px] leading-relaxed text-[#6B756F]">
          {{ field.description }}
        </p>
        <p v-if="field.note" class="text-[12px] leading-relaxed text-[#2F80ED]">
          <span class="font-semibold">{{ field.note.split(':')[0] }}:</span>{{ field.note.includes(':') ? field.note.slice(field.note.indexOf(':') + 1) : '' }}
        </p>
      </div>

      <!-- Other field types: label above input -->
      <template v-else>
        <Label
          :for="fieldId(field)"
          class="text-xs"
          :class="props.variant === 'panel-two' ? 'font-medium text-[#47534D]' : ''"
        >
          <span class="inline-flex items-center gap-1.5">
            <span>{{ field.label }}<span v-if="field.required" class="text-[#E5484D]">*</span></span>
            <Tooltip v-if="field.hint">
              <TooltipTrigger as-child>
                <Button
                  type="button"
                  variant="ghost"
                  size="icon-sm"
                  class="size-4 shrink-0 rounded-full p-0 text-[#7B8781] hover:bg-transparent hover:text-[#2E7D32]"
                  :aria-label="`${field.label}: ${field.hint}`"
                  @click.prevent
                >
                  <Icon name="alert-circle" :size="13" />
                </Button>
              </TooltipTrigger>
              <TooltipContent class="max-w-[240px] text-xs leading-relaxed">
                {{ field.hint }}
              </TooltipContent>
            </Tooltip>
          </span>
        </Label>

        <Select v-if="field.type === 'select'" v-model="(formValues[field.key] as string)" :disabled="isDisabled(field)">
          <SelectTrigger
            :id="fieldId(field)"
            size="sm"
            class="w-full text-xs"
            :class="props.variant === 'panel-two' ? 'h-9 rounded-full border-0 bg-[#EEF5F1] px-3 text-[#27332D] shadow-none ring-0' : ''"
          >
            <SelectValue :placeholder="field.placeholder ?? 'Chọn...'" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem
              v-for="opt in field.options"
              :key="opt.value"
              :value="opt.value"
              class="text-xs"
            >
              {{ opt.label }}
            </SelectItem>
          </SelectContent>
        </Select>

        <Popover v-else-if="field.type === 'searchable-select'" v-model:open="searchableSelectOpen[field.key]">
          <PopoverTrigger as-child>
            <Button
              type="button"
              variant="secondary"
              class="h-9 w-full justify-between rounded-full border-0 bg-[#EEF5F1] px-3 text-left text-xs font-normal text-[#27332D] shadow-none ring-0 hover:bg-[#E6F0EA] disabled:cursor-not-allowed disabled:opacity-60"
              :disabled="isDisabled(field)"
            >
              <span class="truncate">{{ optionLabel(field) || field.placeholder || 'Chọn...' }}</span>
              <Icon name="chevron-down" :size="13" class="shrink-0 text-[#67736C]" />
            </Button>
          </PopoverTrigger>
          <PopoverContent class="w-[280px] rounded-[14px] border-[#BFD8CC] bg-[#F8FFFA] p-2 shadow-xl data-[state=closed]:hidden">
            <Input
              v-model="searchQueries[field.key]"
              :placeholder="field.optionSearchPlaceholder ?? 'Tìm kiếm...'"
              class="mb-2 h-8 rounded-full border-0 bg-white px-3 text-xs text-[#27332D] shadow-none ring-1 ring-[#DCEBE3] placeholder:text-[#8B9690]"
              autocomplete="off"
            />
            <div class="max-h-56 overflow-auto pr-1">
              <Button
                v-for="opt in filteredOptions(field)"
                :key="opt.value"
                type="button"
                variant="ghost"
                class="flex h-auto w-full items-center justify-between gap-2 rounded-[10px] px-2.5 py-1.5 text-left text-xs font-normal text-[#36433C] hover:bg-[#D8E9E1]"
                @click="selectOption(field, opt.value)"
              >
                <span class="min-w-0 truncate">{{ opt.label }}</span>
                <Icon v-if="formValues[field.key] === opt.value" name="check" :size="13" class="shrink-0 text-[#2E7D32]" />
              </Button>
              <p v-if="filteredOptions(field).length === 0" class="px-2 py-4 text-center text-xs text-[#7B8781]">Không có kết quả</p>
            </div>
          </PopoverContent>
        </Popover>

        <RadioGroup
          v-else-if="field.type === 'radio'"
          v-model="(formValues[field.key] as string)"
          class="flex flex-wrap items-center gap-x-6 gap-y-2"
          :disabled="isDisabled(field)"
        >
          <Label
            v-for="opt in field.options"
            :key="opt.value"
            class="flex cursor-pointer items-center gap-2 text-xs font-medium text-[#35433A]"
            :class="isDisabled(field) ? 'cursor-not-allowed' : ''"
          >
            <RadioGroupItem :value="opt.value" />
            <span>{{ opt.label }}</span>
          </Label>
        </RadioGroup>

        <Textarea
          v-else-if="field.type === 'textarea'"
          :id="fieldId(field)"
          v-model="(formValues[field.key] as string)"
          :placeholder="field.placeholder"
          :disabled="isDisabled(field)"
          rows="3"
          class="text-xs"
          :class="props.variant === 'panel-two' ? 'min-h-20 rounded-[16px] border-0 bg-[#EEF5F1] px-3 py-2 text-[#27332D] shadow-none ring-0 placeholder:text-[#8B9690]' : ''"
        />

        <!-- File picker: a file input's value can't be set programmatically,
             so we don't v-model it; on change we store the file NAME (string)
             for visual feedback. The actual File is read when the runner exists.
             The native input forgets its label on remount (toggle off→on), so we
             show the stored name below it to confirm a file is still selected. -->
        <template v-else-if="field.type === 'file'">
          <input
            :id="fieldId(field)"
            type="file"
            :accept="field.accept"
            :disabled="isDisabled(field)"
            class="block w-full text-xs text-foreground file:mr-2 file:rounded file:border-0 file:bg-primary file:px-2 file:py-1 file:text-xs file:text-primary-foreground"
            :class="props.variant === 'panel-two' ? 'rounded-[16px] bg-[#EEF5F1] px-3 py-2 text-[#47534D] file:rounded-full file:bg-white file:text-[#2E7D32]' : ''"
            @change="onFileChange(field.key, $event)"
          />
          <p v-if="formValues[field.key]" class="text-[11px] text-emerald-300/90" :class="props.variant === 'panel-two' ? 'text-[#2E7D32]' : ''">
            Đã chọn: {{ fileLabel(formValues[field.key]) }}
          </p>
        </template>

        <Input
          v-else
          :id="fieldId(field)"
          v-model="(formValues[field.key] as string)"
          :type="field.sensitive ? 'password' : field.type === 'number' ? 'number' : 'text'"
          :placeholder="field.placeholder"
          :disabled="isDisabled(field)"
          autocomplete="off"
          class="h-8 text-xs"
          :class="props.variant === 'panel-two' ? 'h-9 rounded-full border-0 bg-[#EEF5F1] px-3 text-[#27332D] shadow-none ring-0 placeholder:text-[#8B9690]' : ''"
        />
      </template>

    </div>
    </div>
  </TooltipProvider>
</template>
