import { graphql } from '../fb-graph';
import { isGraphError } from '../types';
import type { ToolRunner } from './index';

const RESOLVE_OWNER_DOC_ID = '5746473718752934';
const RESTRICTION_DOC_ID = '8742430529208614';
const CHECKPOINT_BASE = 'https://www.facebook.com/checkpoint/1501092823525282';

interface ResolveOwnerResponse {
  data?: {
    billable_account_by_payment_account?: {
      id?: string;
    };
  };
}

interface RestrictionParams {
  container_id?: string;
  decision_id?: string;
  friction_decision_id?: string;
  ids_issue_ent_id?: string;
  issue_id?: string;
}

interface RestrictionResponse {
  data?: {
    adAccountData?: {
      advertising_restriction_info?: {
        additional_parameters?: RestrictionParams;
      };
    };
  };
}

function bareId(id: string): string {
  return id.startsWith('act_') ? id.slice(4) : id;
}

function findAdditionalParameters(value: unknown): RestrictionParams | null {
  if (!value || typeof value !== 'object') return null;
  const record = value as Record<string, unknown>;
  if ('additional_parameters' in record && record.additional_parameters && typeof record.additional_parameters === 'object') {
    return record.additional_parameters as RestrictionParams;
  }
  for (const child of Object.values(record)) {
    const found = findAdditionalParameters(child);
    if (found) return found;
  }
  return null;
}

async function resolveOwnerId(adId: string): Promise<string> {
  const res = await graphql<ResolveOwnerResponse>({
    doc_id: RESOLVE_OWNER_DOC_ID,
    variables: JSON.stringify({ paymentAccountID: adId }),
  }, 'business');

  if (isGraphError(res)) throw new Error(res.message);
  const ownerId = res.data?.billable_account_by_payment_account?.id;
  if (!ownerId) throw new Error('Không resolve được asset owner id từ paymentAccountID');
  return ownerId;
}

async function loadRestrictionParams(ownerId: string, adId: string): Promise<RestrictionParams | null> {
  const res = await graphql<RestrictionResponse>({
    doc_id: RESTRICTION_DOC_ID,
    fb_api_req_friendly_name: 'useAccountQualityHubIssueQueryWrapperQuery',
    variables: JSON.stringify({ assetOwnerId: ownerId, assetId: adId }),
  }, 'www');

  if (isGraphError(res)) throw new Error(res.message);
  return res.data?.adAccountData?.advertising_restriction_info?.additional_parameters ?? findAdditionalParameters(res);
}

export const getXmdtLink: ToolRunner = async (account) => {
  const adId = bareId(account.id || account.account_id || '');
  if (!adId) return { ok: false, message: 'Thiếu ID tài khoản quảng cáo' };

  const ownerId = await resolveOwnerId(adId);
  const params = await loadRestrictionParams(ownerId, adId);
  if (!params || (!params.container_id && !params.decision_id && !params.friction_decision_id)) {
    return { ok: true, skipped: true, message: 'TKQC không có link XMDT hoặc response chưa có restriction params' };
  }

  return {
    ok: false,
    message: `Đã resolve owner ${ownerId} và restriction params, nhưng chưa gửi ufac vì docs yêu cầu capture live session fields (__dyn/__rev/__hsi/session_id/jazoest) trước khi đấu API. Params: ${JSON.stringify(params)}`,
  };
};

export function buildCheckpointLink(enrollmentId: string): string {
  return `${CHECKPOINT_BASE}/${encodeURIComponent(enrollmentId)}`;
}
